function smokeCategoryFor(tempC){
  if(tempC<=30) return 'cold';
  if(tempC<=60) return 'warm';
  return 'hot';
}

const DEFAULT_G_PER_TSP = 6.0;

const LB_TO_KG = 0.453592;

const KG_PER_5LB = 5 * LB_TO_KG;

const ML_PER_TSP = 5;

const ML_PER_CUP = 236.588;

function scaleInoculant(ing, totalKg){
  if(!ing) return null;
  const tspPer5lb = +ing.starterTsp || 0;
  const mlPer5lb = (+ing.waterMlPer5lb) || ((+ing.waterCupsPer5lb || 0) * ML_PER_CUP);
  const cupsPer5lb = mlPer5lb / ML_PER_CUP;
  const rehydMin = +ing.rehydMin || 30;
  if(!tspPer5lb) return null;
  const units5lb = totalKg / KG_PER_5LB;
  const starterTsp = tspPer5lb * units5lb;
  const waterMl = mlPer5lb * units5lb;
  const waterCups = waterMl / ML_PER_CUP;
  return {
    starterTsp,
    starterMl: starterTsp * ML_PER_TSP,
    waterCups,
    waterMl,
    rehydMin,
    tspPer5lb, cupsPer5lb, mlPer5lb, units5lb
  };
}

function fmtFrac(x, precision){
  if(!isFinite(x) || x <= 0) return '0';
  const whole = Math.floor(x);
  const frac = x - whole;
  const frags = [
    [0, ''], [0.125, '1/8'], [0.1667, '1/6'], [0.25, '1/4'], [0.333, '1/3'],
    [0.375, '3/8'], [0.5, '1/2'], [0.625, '5/8'], [0.667, '2/3'], [0.75, '3/4'],
    [0.875, '7/8'], [1, '']
  ];
  let best = null, bestDiff = 0.04;
  for(const [v, label] of frags){
    const d = Math.abs(frac - v);
    if(d < bestDiff){ best = [v, label]; bestDiff = d; }
  }
  if(best){
    if(best[0] === 0) return String(whole);
    if(best[0] === 1) return String(whole+1);
    return whole > 0 ? `${whole} ${best[1]}` : best[1];
  }
  return x.toFixed(precision||2);
}

