const NITRITE_MAX_PPM = 625;

const NITRATE_MAX_PPM = 2187;

const NITRITE_TARGET_PPM = 200;

const NITRITE_WARN_PPM = 500;

const DEFAULT_CAVA_TEMP = 13;

const DEFAULT_CAVA_PH   = 5.8;

const RESIDUAL_TYPICAL_NITRITE_PPM = 13.7;

const RESIDUAL_TYPICAL_NITRATE_PPM = 32.6;

function nitriteHalfLifeDays(tempC, ph){
  // Nordin: log10(t_half hours) = 0.65 - 0.025*T + 0.35*pH
  const logH = 0.65 - 0.025*tempC + 0.35*ph;
  return Math.pow(10, logH) / 24;
}

function nitrateHalfLifeDays(tempC, ph){
  // Nitrate is ~3-4x more stable than nitrite at typical cave conditions
  return nitriteHalfLifeDays(tempC, ph) * 3.5;
}

function calcResidualNitrite(ingoingPpm, days, tempC, ph){
  if(!ingoingPpm) return 0;
  const half = nitriteHalfLifeDays(tempC, ph);
  return ingoingPpm * Math.pow(0.5, days/half);
}

function calcResidualNitrate(ingoingPpm, days, tempC, ph){
  if(!ingoingPpm) return 0;
  const half = nitrateHalfLifeDays(tempC, ph);
  return ingoingPpm * Math.pow(0.5, days/half);
}

function nitriteFromNitrateReduction(ingoingNitratePpm, days, tempC, ph){
  if(!ingoingNitratePpm) return 0;
  // Approximate: about 25% of degraded nitrate momentarily exists as nitrite,
  // that nitrite has time (days/2) to decay before end of process.
  const halfNitrate = nitrateHalfLifeDays(tempC, ph);
  const nitrateLost = ingoingNitratePpm * (1 - Math.pow(0.5, days/halfNitrate));
  const transientNitrite = nitrateLost * 0.25;
  const halfNitrite = nitriteHalfLifeDays(tempC, ph);
  return transientNitrite * Math.pow(0.5, (days/2)/halfNitrite);
}

function calcFullResidual(ingoingNitritePpm, ingoingNitratePpm, days, tempC, ph){
  const directResidualNitrite = calcResidualNitrite(ingoingNitritePpm, days, tempC, ph);
  const derivedNitrite = nitriteFromNitrateReduction(ingoingNitratePpm, days, tempC, ph);
  const residualNitrite = directResidualNitrite + derivedNitrite;
  // A fraction (~12%) of the degraded nitrite is re-oxidized to shelf-stable nitrate
  // during long dry-cure aging. This is the biochemical basis for why aged prosciutto
  // has more nitrate than nitrite in its residual profile.
  const degradedNitrite = ingoingNitritePpm - directResidualNitrite;
  const nitrateFromNitriteOxidation = Math.max(0, degradedNitrite * 0.12);
  const residualNitrate = calcResidualNitrate(ingoingNitratePpm, days, tempC, ph) + nitrateFromNitriteOxidation;
  return {
    residualNitrite,
    residualNitrate,
    halfLifeNitrite: nitriteHalfLifeDays(tempC, ph),
    halfLifeNitrate: nitrateHalfLifeDays(tempC, ph),
    nitrateFromNitriteOxidation,
    reductionNitrite: 100 * (1 - residualNitrite/(ingoingNitritePpm||1)),
    reductionNitrate: ingoingNitratePpm ? 100 * ((ingoingNitratePpm - calcResidualNitrate(ingoingNitratePpm, days, tempC, ph))/ingoingNitratePpm) : 0
  };
}

function totalCureProcessDays(type){
  if(!type || !type.stages) return 0;
  return type.stages.reduce((s, st)=> s + (+st.dEst||0), 0);
}

function totalCureProcessDaysBatch(batch){
  if(!batch || !batch.stages) return 0;
  return batch.stages.reduce((s, st)=> s + (+st.dEst||0), 0);
}

function calcCureContribution(brine, meatG){
  const cure = brine?.cureSalt;
  if(!cure || !cure.ingredient || !(+cure.gPerKg > 0)){
    return { cureG:0, naclFromCure:0, nitritePpm:0, nitratePpm:0, level:'gray', maxCureG:0, cureIng:null };
  }
  const ing = cureSaltByName(cure.ingredient);
  if(!ing){
    return { cureG:0, naclFromCure:0, nitritePpm:0, nitratePpm:0, level:'gray', maxCureG:0, cureIng:null };
  }
  const meatKg = meatG / 1000;
  const cureG = (+cure.gPerKg) * meatKg;
  const nitritePct = +ing.nitritePct || 0;
  const nitratePct = +ing.nitratePct || 0;
  const naclPct = +ing.naclPct || 0;
  const maxGPerKg = +ing.maxGPerKg || 4.0;
  const nitritePpm = (cureG * nitritePct/100) * 1e6 / meatG;
  const nitratePpm = (cureG * nitratePct/100) * 1e6 / meatG;
  const naclFromCure = cureG * naclPct/100;
  let level = 'green';
  if(nitritePpm > NITRITE_MAX_PPM || nitratePpm > NITRATE_MAX_PPM || (+cure.gPerKg) > maxGPerKg) level = 'red';
  else if(nitritePpm > NITRITE_WARN_PPM) level = 'yellow';
  else if(nitritePpm > NITRITE_TARGET_PPM) level = 'yellow';
  return { cureG, naclFromCure, nitritePpm, nitratePpm, level, maxCureG: maxGPerKg*meatKg, cureIng: ing };
}

function calcCureResidual(cureResult, days, tempC, ph){
  if(!cureResult || !cureResult.cureIng || !days) return null;
  const t = tempC || DEFAULT_CAVA_TEMP;
  const p = ph || DEFAULT_CAVA_PH;
  const r = calcFullResidual(cureResult.nitritePpm, cureResult.nitratePpm, days, t, p);
  return { ...r, days, tempC:t, ph:p };
}

function saltByName(name){
  return db.ingredients.find(i => i.name===name && (i.category==='sal'||i.category==='sal-curado'));
}

function saltDensity(name){
  const s = saltByName(name);
  return (s && +s.gPerTsp) ? +s.gPerTsp : DEFAULT_G_PER_TSP;
}

function defaultSaltName(){
  const salts = saltIngredients();
  // prefer a plain 'sal' category, else first available
  const plain = salts.find(s => s.category==='sal');
  return (plain || salts[0])?.name || '';
}

