function calcEqBrine(meatG, saltPct, waterPct, saltName, cureBrine){
  const waterG = meatG * (waterPct/100);
  const totalTargetG = (meatG + waterG) * (saltPct/100);
  const cure = calcCureContribution(cureBrine || { cureSalt: null }, meatG);
  const commonG = Math.max(0, totalTargetG - cure.naclFromCure);
  const totalNaCl = commonG + cure.naclFromCure;
  const totalG = meatG + waterG + commonG + cure.cureG;
  const gPerTsp = saltDensity(saltName);
  const commonTsp = commonG / gPerTsp;
  const finalPct = (totalNaCl / totalG) * 100;
  const saltObj = saltByName(saltName) || { name: saltName || 'Sal', gPerTsp };
  return {
    waterG, totalG, finalPct, salt: saltObj,
    commonG, commonTsp,
    cureG: cure.cureG,
    cureTsp: cure.cureIng ? cure.cureG / ((+cure.cureIng.gPerTsp) || DEFAULT_G_PER_TSP) : 0,
    cureIng: cure.cureIng,
    naclFromCure: cure.naclFromCure,
    nitritePpm: cure.nitritePpm,
    nitratePpm: cure.nitratePpm,
    cureLevel: cure.level,
    maxCureG: cure.maxCureG,
    saltG: commonG,
    saltTsp: commonTsp
  };
}

