function normalizeUnit(u){
  if(!u) return 'g';
  const s = String(u).toLowerCase().trim();
  const map = {
    'oz':'g', 'lb':'g', 'lbs':'g', 'pound':'g',
    'tsp':'g', 'tbsp':'g', 'cup':'ml', 'cups':'ml', 'fl oz':'ml',
    'in':'cm', 'inch':'cm', 'inches':'cm',
    'f':'C', 'fahrenheit':'C',
    'gramos':'g', 'gramo':'g', 'grams':'g', 'gram':'g',
    'mililitros':'ml', 'mililitro':'ml', 'milliliter':'ml',
    'litros':'L', 'litro':'L', 'liter':'L', 'l':'L',
    'centimetros':'cm', 'centimetro':'cm',
    'celsius':'C', 'grados':'C'
  };
  return map[s] || s;
}

function saveDB(){
  saveDBLocal();
  if(typeof autoBackup==='function') autoBackup();
  if(typeof icloudDebouncedPush==='function') icloudDebouncedPush();
}

function loadDB(){
  const raw = localStorage.getItem(LS_KEY);
  if(raw){
    try{ db = JSON.parse(raw); migrateSalts(); migrateWeightLogsToPieces();
  migrateBackfillBrineOnBatches();
  migrateStripSaltFromCureBatches();
  if(typeof migrateBaseMeat==='function') migrateBaseMeat();
  if(typeof migrateTastings==='function') migrateTastings();
  return true; } catch(e){}
  }
  return false;
}

function migrateSalts(){
  const legacy = {fine_sea:'Sal marina fina', table:'Sal de mesa', diamond:'Diamond Crystal Kosher',
                  morton:'Morton Kosher', himalaya:'Sal rosada del Himalaya', maldon:'Sal en escamas (Maldon)'};
  let touched = false;
  const cureData = {
    'InstaCure #1': { nitritePct:6.25, nitratePct:0, naclPct:93.75, maxGPerKg:4.0 },
    'InstaCure #2': { nitritePct:6.25, nitratePct:4.0, naclPct:89.75, maxGPerKg:4.0 }
  };
  (db.ingredients||[]).forEach(ing=>{
    if(ing.category==='sal-curado' && cureData[ing.name]){
      const d = cureData[ing.name];
      if(ing.nitritePct===undefined){ ing.nitritePct = d.nitritePct; touched = true; }
      if(ing.nitratePct===undefined){ ing.nitratePct = d.nitratePct; touched = true; }
      if(ing.naclPct===undefined){ ing.naclPct = d.naclPct; touched = true; }
      if(ing.maxGPerKg===undefined){ ing.maxGPerKg = d.maxGPerKg; touched = true; }
    }
  });
  (db.types||[]).forEach(t=>{
    (t.stages||[]).forEach(s=>{
      if(s.kind==='Curado' && s.brine && s.brine.cureSalt===undefined){
        s.brine.cureSalt = { ingredient:null, gPerKg:0 };
        touched = true;
      }
      // Strip salt/cure-salt entries from Curado stage recipes (they belong to brine now)
      if(s.kind==='Curado' && Array.isArray(s.recipe)){
        const before = s.recipe.length;
        s.recipe = s.recipe.filter(r=>{
          const ing = db.ingredients.find(x=>x.name===r.ingredient);
          return !ing || (ing.category!=='sal' && ing.category!=='sal-curado');
        });
        if(s.recipe.length !== before) touched = true;
      }
    });
  });
  (db.types||[]).forEach(t=>(t.stages||[]).forEach(s=>{
    if(s.brine && s.brine.saltId && !s.brine.saltIngredient){
      s.brine.saltIngredient = legacy[s.brine.saltId] || 'Sal marina fina';
      delete s.brine.saltId; touched = true;
    }
  }));
  (db.batches||[]).forEach(b=>(b.stages||[]).forEach(s=>{
    if(s.brine && s.brine.saltId && !s.brine.saltIngredient){
      s.brine.saltIngredient = legacy[s.brine.saltId] || 'Sal marina fina';
      delete s.brine.saltId; touched = true;
    }
  }));
  // Ensure any salt ingredient without density gets a sensible default so brine math works
  (db.ingredients||[]).forEach(i=>{
    if((i.category==='sal'||i.category==='sal-curado') && (i.gPerTsp===undefined)){
      i.gPerTsp = null; touched = true;
    }
  });
  if(touched){ try{ localStorage.setItem(LS_KEY, JSON.stringify(db)); }catch(e){} }
}

function seedDB(){
  db.ingredients = [];
  db.types = [];
  db.batches = [];
  saveDB();
}

function loadExampleRecipe(){
  const existingNames = new Set(db.ingredients.map(i=>i.name));
  SEED_INGREDIENTS.forEach((s,i)=>{
    if(existingNames.has(s.n)) return;
    db.ingredients.push({ id:uid('ing'), name:s.n, unit:s.u, category:s.cat, note:s.note||'', gPerTsp: s.gPerTsp||null, ...(s.nutr?{nutr: {...s.nutr}}:{}) });
  });
  const existingTypeNames = new Set(db.types.map(t=>t.name));
  SEED_TYPES.forEach((t,ti)=>{
    if(existingTypeNames.has(t.n)) return;
    db.types.push({
      id:uid('typ'), name:t.n, ref:t.ref, category:t.cat,
      notes:t.notes,
      yield: t.yield,
      stages: t.stages.map((s,si)=>({
        id:uid('stg'),
        kind: s.k, dEst: s.dEst,
        eb: s.eb||false, shape: s.shape||null,
        brine: s.brine || (s.k==='Curado' ? {saltPct:2.8, waterPct:0, saltIngredient:'Sal marina fina', cureSalt:{ingredient:null, gPerKg:0}} : null),
        press: false,
        env: s.env||null,
        ph: s.ph||null,
        inoc: s.inoc||null,
        smoke: s.smoke||null,
        recipe: (s.recipe||[]).map(r=>({ ingredient:r.i, amount:r.a, note:r.note||'' })),
      }))
    });
  });
  if(typeof migrateBaseMeat==='function') migrateBaseMeat();
  saveDB(); render();
  toast('Receta de ejemplo cargada: Lomo Español');
}

function applyLibraryImport(payload){
  // Acepta biblioteca completa, solo-ingredientes, solo-recetas, o un export completo de DB
  const srcIngs  = payload.ingredients || [];
  const srcTypes = payload.types || [];
  if(!srcIngs.length && !srcTypes.length){ toast('El archivo no contiene recetas ni ingredientes'); return; }
  let ingNew = 0, ingUpd = 0, typNew = 0, typUpd = 0;

  // Merge ingredientes por nombre: actualiza campos, conserva id local
  srcIngs.forEach(src=>{
    const local = db.ingredients.find(i=>i.name===src.name);
    if(local){
      ['unit','category','note','gPerTsp','nutr','meat','nitritePct','nitratePct','naclPct','maxGPerKg','starterTsp','waterMlPer5lb','rehydMin'].forEach(k=>{
        if(src[k] !== undefined) local[k] = src[k];
      });
      ingUpd++;
    } else {
      const { id, ...rest } = src;
      db.ingredients.push({ id: uid('ing'), ...rest });
      ingNew++;
    }
  });

  // Merge recetas por nombre: actualiza definición, conserva id local (los lotes referencian typeId)
  srcTypes.forEach(src=>{
    const local = db.types.find(t=>t.name===src.name);
    if(local){
      ['ref','category','notes','yield','stages','baseMeat','servingG'].forEach(k=>{
        if(src[k] !== undefined) local[k] = JSON.parse(JSON.stringify(src[k]));
      });
      typUpd++;
    } else {
      const { id, ...rest } = src;
      db.types.push({ id: uid('typ'), ...JSON.parse(JSON.stringify(rest)) });
      typNew++;
    }
  });

  // Si importamos recetas que referencian ingredientes (por nombre) que no existen
  // en el catálogo local, avisamos — el cálculo de nutrición/receta seguirá
  // funcionando por nombre, pero sin perfil nutricional hasta que se agreguen.
  const referencedNames = new Set();
  srcTypes.forEach(t=>{
    (t.stages||[]).forEach(s=>{
      (s.recipe||[]).forEach(r=>{ if(r.ingredient) referencedNames.add(r.ingredient); });
      if(s.brine?.saltIngredient) referencedNames.add(s.brine.saltIngredient);
      if(s.brine?.cureSalt?.ingredient) referencedNames.add(s.brine.cureSalt.ingredient);
      if(s.inoc?.i) referencedNames.add(s.inoc.i);
    });
    (t.baseMeat?.composition||[]).forEach(c=>{ if(c.ingredient) referencedNames.add(c.ingredient); });
  });
  const missing = [...referencedNames].filter(n => !db.ingredients.some(i=>i.name===n));

  if(typeof migrateBaseMeat==='function') migrateBaseMeat();
  saveDB(); render();
  const parts = [];
  if(srcTypes.length) parts.push(`${typNew} recetas nuevas, ${typUpd} actualizadas`);
  if(srcIngs.length) parts.push(`${ingNew} ingredientes nuevos, ${ingUpd} actualizados`);
  let msg = `✓ ${parts.join(' · ')}`;
  if(missing.length){
    msg += ` · ⚠ ${missing.length} ingrediente${missing.length===1?'':'s'} sin catálogo: ${missing.slice(0,4).join(', ')}${missing.length>4?'…':''}`;
  }
  toast(msg);
}

function restoreSalts(){
  let added = 0, patched = 0;
  SEED_SALTS.forEach(s=>{
    const existing = db.ingredients.find(i=>i.name===s.n);
    if(!existing){
      db.ingredients.push({ id:uid('ing'), name:s.n, unit:s.u, category:s.cat, note:s.note||'', gPerTsp:s.gPerTsp||null });
      added++;
    } else {
      // ensure category + density are set for salts that already exist by name
      if((existing.category==='sal'||existing.category==='sal-curado') && (existing.gPerTsp===null||existing.gPerTsp===undefined)){
        existing.gPerTsp = s.gPerTsp||null; patched++;
      }
    }
  });
  saveDB(); render();
  if(added||patched){
    toast(`Sales repuestas: ${added} nueva${added===1?'':'s'}${patched?`, ${patched} con densidad`:''}`);
  } else {
    toast('Todas las sales ya estaban presentes');
  }
}

function resetDB(){
  if(!confirm('Esto BORRA todo: ingredientes, recetas y lotes. La app queda en blanco. Se perderán lotes y ediciones. ¿Continuar?')) return;
  seedDB(); render(); toast('Datos borrados — app en blanco. Importá tu Biblioteca JSON o creá desde cero.');
}

const AW_TARGET_BY_CATEGORY = {
  'muscular':   0.93,
  'embutido':   0.92,
  'ahumado':    0.93,
  'default':    0.93
};

const AW_NO_BARRIER = 0.94;

function awTargetForType(type){
  if(!type) return AW_TARGET_BY_CATEGORY.default;
  if(typeof type.awTarget === 'number' && type.awTarget > 0) return type.awTarget;
  const key = (type.category||'').toLowerCase();
  for(const k of Object.keys(AW_TARGET_BY_CATEGORY)){
    if(key.includes(k)) return AW_TARGET_BY_CATEGORY[k];
  }
  return AW_TARGET_BY_CATEGORY.default;
}

function calcAw({greenG, currentG, saltPct, sucrosePct=0, waterFracGreen=0.74}){
  if(!greenG || greenG <= 0 || !currentG || currentG <= 0) return null;
  if(currentG > greenG * 1.05) return null; // sanity: gained >5% is weird
  const naClG = (saltPct||0)/100 * greenG;
  const waterInit = waterFracGreen * greenG;
  const waterLost = Math.max(0, greenG - currentG);
  const waterNow = Math.max(0.01 * currentG, waterInit - waterLost);
  const mNaClPct = 100 * naClG / waterNow;
  let aw = 1 - 0.0085 * mNaClPct - 0.00013 * (sucrosePct||0);
  aw = Math.max(0.4, Math.min(0.995, aw));
  return aw;
}

function targetWeightForAw({greenG, awTarget, saltPct, sucrosePct=0, waterFracGreen=0.74}){
  if(!greenG || !awTarget || !saltPct) return null;
  const naClG = (saltPct/100) * greenG;
  const sugarTerm = 0.00013 * (sucrosePct||0);
  const target_mNaClPct = (1 - awTarget - sugarTerm) / 0.0085;
  if(target_mNaClPct <= 0) return null; // target already met at saturation
  const waterNow = 100 * naClG / target_mNaClPct;
  const waterInit = waterFracGreen * greenG;
  const waterLost = waterInit - waterNow;
  const currentG = greenG - waterLost;
  if(currentG <= 0 || currentG > greenG) return null;
  return currentG;
}

const AW_K = 0.0085;

const AW_CAL_MIN = 2;

const AW_UNC_EST = 0.03;

const AW_UNC_CAL = 0.02;

const AW_UNC_MED = 0.015;

function typeWaterFrac(type){
  const w = type && type.waterFrac;
  return (typeof w==='number' && w>0.4 && w<0.85) ? w : 0.74;
}

function pieceSaltInfo(b, piece){
  let saltG = 0, found = false;
  (b.stages||[]).forEach(st=>{
    if(st.brine && +st.brine.saltPct > 0){
      try{
        const r = calcEqBrine(piece.initialWeight||0, +st.brine.saltPct, +st.brine.waterPct||0, st.brine.saltIngredient, st.brine);
        saltG += (r.commonG||0) + (r.naclFromCure||0);
      }catch(e){ saltG += (+st.brine.saltPct/100) * (piece.initialWeight||0); }
      found = true;
    }
  });
  if(!found) saltG = 0.028 * (piece.initialWeight||0);
  return { saltG, assumed: !found };
}

function pieceAwModel(b, piece, currentG, type){
  type = type || db.types.find(t=>t.id===b.typeId);
  const green = piece.initialWeight;
  if(!green || green <= 0 || !currentG || currentG <= 0) return null;
  if(currentG > green * 1.5) return null; // sanity
  const { saltG } = pieceSaltInfo(b, piece);
  const tare = +piece.tare > 0 ? +piece.tare : 0;
  const nonWater = (1 - typeWaterFrac(type)) * green + saltG + tare;
  const waterNow = Math.max(0.01 * currentG, currentG - nonWater);
  const aw = 1 - AW_K * (100 * saltG / waterNow);
  return Math.max(0.4, Math.min(0.995, aw));
}

function awReadings(piece){
  return (piece.awReadings||[]).filter(r=>r && r.aw>0).slice().sort((a,b)=>new Date(a.date)-new Date(b.date));
}

function typeAwCalibration(typeId){
  const diffs = [];
  db.batches.filter(b=>b.typeId===typeId).forEach(b=>{
    (b.pieces||[]).forEach(p=> awReadings(p).forEach(r=>{
      if(r.weightG > 0){
        const m = pieceAwModel(b, p, r.weightG);
        if(m != null) diffs.push(r.aw - m);
      }
    }));
  });
  const n = diffs.length;
  const bias = n ? diffs.reduce((a,x)=>a+x,0)/n : 0;
  return { n, bias, applied: n >= AW_CAL_MIN };
}

const _clampAw = v => Math.max(0.4, Math.min(0.995, v));

function pieceAwState(b, piece, atWeight){
  const type = db.types.find(t=>t.id===b.typeId);
  const cur = atWeight || latestPieceWeight(piece, b);
  const raw = pieceAwModel(b, piece, cur, type);
  const cal = typeAwCalibration(b.typeId);
  const reads = awReadings(piece);
  const last = reads[reads.length-1] || null;
  const saltAssumed = pieceSaltInfo(b, piece).assumed;
  const manual = (type && typeof type.awOffset==='number') ? type.awOffset : 0;
  if(raw == null) return { aw: last ? last.aw : null, raw:null, offset:0, manual, source: last?'medido':'estimado', unc: last?AW_UNC_MED:AW_UNC_EST, last, cal, saltAssumed };
  let offset = (cal.applied ? cal.bias : 0) + manual, source = 'estimado';
  let unc = cal.applied ? AW_UNC_CAL : AW_UNC_EST;
  if(last){
    const mAt = last.weightG > 0 ? pieceAwModel(b, piece, last.weightG, type) : null;
    offset = (mAt != null) ? (last.aw - mAt) : (last.aw - raw);
    source = 'medido'; unc = AW_UNC_MED;
  }
  return { aw: _clampAw(raw + offset), raw, offset, manual, source, unc, last, cal, saltAssumed };
}

function awTxt(st, short){
  if(!st || st.aw==null) return '—';
  return st.source==='medido'
    ? `${st.aw.toFixed(3)}${short?'':' (medido)'}`
    : `≈ ${st.aw.toFixed(3)} ± ${st.unc.toFixed(2)}${short?' est.':' (estimado, no medido)'}`;
}

function targetWeightForAwPiece(b, piece, awTarget){
  const type = db.types.find(t=>t.id===b.typeId);
  const green = piece.initialWeight;
  if(!green || !awTarget) return null;
  const st = pieceAwState(b, piece);
  const { saltG } = pieceSaltInfo(b, piece);
  if(!(saltG > 0)) return null;
  const modelTarget = awTarget - (st.offset||0);
  const conc = (1 - modelTarget) / AW_K;
  if(conc <= 0) return null;
  const waterTarget = 100 * saltG / conc;
  const tare = +piece.tare > 0 ? +piece.tare : 0;
  const w = waterTarget + (1 - typeWaterFrac(type)) * green + saltG + tare;
  return (w > 0 && w <= green * 1.5) ? w : null;
}

function safetyStatus(b, piece){
  const type = db.types.find(t=>t.id===b.typeId);
  const awTarget = awTargetForType(type);
  let saltPct = 2.8;
  (b.stages||[]).forEach(s=>{
    if(s.brine && typeof s.brine.saltPct === 'number' && s.brine.saltPct > 0) saltPct = s.brine.saltPct;
  });
  const ast = pieceAwState(b, piece);
  const aw = ast.aw, awSource = ast.source;
  const allStagesDone = (b.stages||[]).every(s=>s.done);
  let haccpBlock = null, haccpWhy = null, haccpDoc = 0, haccpAccepted = 0;
  if(typeof evaluateHaccp === 'function'){
    const hac = evaluateHaccp(b);
    const failing = hac.results.find(r=>r.status==='fail' && r.pcc.severity==='critical') || hac.results.find(r=>r.status==='fail');
    if(hac.summary.criticalFails > 0){
      haccpBlock = `${hac.summary.criticalFails} PCC crítico violado`;
    } else if(hac.summary.fail > 0){
      haccpBlock = `${hac.summary.fail} PCC violado`;
    }
    if(haccpBlock && failing) haccpWhy = `${failing.pcc.label} — ${failing.detail}`;
    haccpAccepted = hac.summary.accepted || 0;
    haccpDoc = (hac.summary.documented || 0) - haccpAccepted;
  }
  const base = { aw, awTarget, saltPct, haccpBlock, haccpWhy, awSource, awUnc: ast.unc };
  const awLbl = awSource==='medido' ? `aw ${aw!=null?aw.toFixed(3):''} (medido)` : `aw ≈ ${aw!=null?aw.toFixed(3):''} est.`;
  if(aw === null){
    return { ...base, ready:false, label:'Sin registro de peso', level:'gray' };
  }
  if(haccpBlock){
    return { ...base, ready:false, label:`BLOQUEADA · ${haccpBlock}`, level:'red' };
  }
  if(aw <= awTarget && allStagesDone){
    return { ...base, haccpBlock:null, haccpWhy:null, ready:true, label:`LISTA · ${awLbl}`, level:'green' };
  }
  if(aw <= awTarget && !allStagesDone){
    return { ...base, haccpBlock:null, haccpWhy:null, ready:false, label:`aw OK, etapas pendientes`, level:'yellow' };
  }
  if(haccpAccepted > 0 && haccpDoc === 0 && allStagesDone){
    return { ...base, haccpBlock:null, haccpWhy:null, ready:true, manual:true, label:`LISTA · aceptada manualmente · ${awLbl} (meta ≤ ${awTarget.toFixed(2)})`, level:'green' };
  }
  if(haccpDoc > 0 || haccpAccepted > 0){
    return { ...base, haccpBlock:null, haccpWhy:null, ready:false, label:`En secado · desviación documentada · ${awLbl} (meta ≤ ${awTarget.toFixed(2)})`, level:'yellow' };
  }
  if(aw <= awTarget + 0.01){
    return { ...base, haccpBlock:null, haccpWhy:null, ready:false, label:`Cerca · ${awLbl} / ${awTarget.toFixed(2)}`, level:'yellow' };
  }
  return { ...base, haccpBlock:null, haccpWhy:null, ready:false, label:`NO CONSUMIR AÚN · ${awLbl}`, level:'red' };
}

function isWeightSuspicious(piece, newWeightG, newDateISO){
  const logs = (piece.weightLogs||[]).slice().sort((a,b)=>new Date(a.date)-new Date(b.date));
  const prev = logs.length > 0 ? logs[logs.length-1] : null;
  const baselineW = prev ? prev.weight : piece.initialWeight;
  const baselineDate = prev ? new Date(prev.date) : null;
  const newDate = new Date(newDateISO);
  if(baselineW <= 0) return null;
  const delta = newWeightG - baselineW;
  const deltaPct = 100 * delta / baselineW;
  // Gain of any amount > 1% is suspect
  if(deltaPct > 1){
    return { kind:'gain', pct:deltaPct, msg:`Ganancia inusual de ${deltaPct.toFixed(1)}% desde registro previo` };
  }
  // Loss > 5% within 24h is suspect
  if(baselineDate){
    const hours = (newDate - baselineDate) / (1000*60*60);
    if(hours > 0 && hours < 24 && deltaPct < -5){
      return { kind:'fast-loss', pct:deltaPct, hours, msg:`Pérdida de ${Math.abs(deltaPct).toFixed(1)}% en ${hours.toFixed(1)}h — ¿error de báscula?` };
    }
  }
  return null;
}

function saturationVaporPressure(tempC){
  return 0.6108 * Math.exp(17.27 * tempC / (tempC + 237.3));
}

function vaporPressureDeficit(tempC, hrPct){
  if(tempC===null || hrPct===null) return null;
  return (1 - hrPct/100) * saturationVaporPressure(tempC);
}

function dryingRateK({tempC=13, hrPct=75, thicknessCm=6, shape='tubular'}){
  const vpd = vaporPressureDeficit(tempC, hrPct);
  const vpdRef = vaporPressureDeficit(13, 75); // ~0.374 kPa
  if(!vpd || vpd<=0) return 0;
  const L = Math.max(0.5, (thicknessCm||6)/2); // half-thickness cm
  const Lref = 3; // half-thickness reference
  const geom = shape==='flat' ? 0.65 : 1.0; // flat dries faster per volume
  const kRef = 0.012; // 1/d calibrated reference
  return kRef * (vpd/vpdRef) * Math.pow(Lref/L, 2) * geom;
}

function theoreticalWeightAt({W0, Wtarget, k, t}){
  if(!k || k<=0) return W0;
  return Wtarget + (W0 - Wtarget) * Math.exp(-k * t);
}

function envStats(b, stageKind=null){
  if(!b.envLog || b.envLog.length === 0) return null;
  let logs = b.envLog;
  if(stageKind) logs = logs.filter(l => l.stageKind===stageKind || !l.stageKind);
  const ts = logs.map(l=>l.tempC).filter(v=>v!==null && !isNaN(v));
  const hs = logs.map(l=>l.hr).filter(v=>v!==null && !isNaN(v));
  if(ts.length===0 && hs.length===0) return null;
  const avg = arr => arr.length ? arr.reduce((s,v)=>s+v,0)/arr.length : null;
  return {
    avgT: avg(ts),
    avgHR: avg(hs),
    nSamples: logs.length,
    kind: stageKind
  };
}

function caseHardeningRisk(b, piece){
  const stats = envStats(b, 'Secado') || envStats(b, 'Madurado') || envStats(b);
  if(!stats || stats.avgT===null || stats.avgHR===null) return null;
  const vpd = vaporPressureDeficit(stats.avgT, stats.avgHR);
  // Safe VPD threshold scales with piece grosor: thicker piece → lower safe VPD
  // Reference: 6cm thickness, safe VPD ≈ 0.45 kPa (ambient 13°C/70%HR = 0.448)
  const safeVpd = 0.45 * (6 / Math.max(2, piece.thickness||6));
  const ratio = vpd / safeVpd;
  const risk = ratio > 1.2;
  let msg = '';
  if(risk){
    const hrSuggest = Math.min(90, Math.round(stats.avgHR + 10));
    msg = `Riesgo case hardening (ratio ${ratio.toFixed(2)}) — considera subir HR a ${hrSuggest}%`;
  }
  return { risk, ratio, vpd, safeVpd, avgT: stats.avgT, avgHR: stats.avgHR, msg };
}

function massBalance(b){
  const greenG = b.pieces.reduce((s,p)=>s + (p.initialWeight||0), 0);
  const currentG = b.pieces.reduce((s,p)=>s + latestPieceWeight(p), 0);
  // Salt added: sum of saltPct from all stages × greenG (approx)
  let saltG = 0;
  (b.stages||[]).forEach(s=>{
    if(s.brine && s.brine.saltPct){
      saltG += (s.brine.saltPct/100) * greenG;
    }
  });
  // Add cure salt if present
  (b.stages||[]).forEach(s=>{
    if(s.brine && s.brine.cureSalt && s.brine.cureSalt.gPerKg){
      saltG += s.brine.cureSalt.gPerKg * (greenG/1000);
    }
  });
  // Theoretical: water evaporated = greenG + saltG - currentG, under ideal (no misc loss)
  // In practice there's drip loss, mold removed, etc. Compare measured vs expected water loss
  // using an assumption: 100% of weight change beyond salt is water
  const theoreticalInput = greenG + saltG;
  const totalDelta = theoreticalInput - currentG; // positive = net loss
  // Water loss cap: can't exceed green water content (~74% of green)
  const maxPossibleWater = 0.74 * greenG;
  const waterLostG = Math.min(totalDelta, maxPossibleWater);
  const unexplainedG = totalDelta - waterLostG;
  const unexplainedPct = greenG > 0 ? 100 * unexplainedG / greenG : 0;
  const balanced = Math.abs(unexplainedPct) <= 2;
  return { greenG, saltG, currentG, waterLostG, unexplainedG, unexplainedPct, totalDelta, balanced };
}

const HAZARD_CATALOG = {
  'muscular': {
    biologicos: ['Listeria monocytogenes','Salmonella spp.','S. aureus','Toxoplasma gondii','Trichinella (cerdo)','E. coli STEC'],
    quimicos: ['Nitrito residual (ADI 0.07 mg/kg)','Micotoxinas (moho malo)','Metales pesados (carne contaminada)'],
    fisicos: ['Fragmentos óseos','Fragmentos metálicos','Pelo o fibras']
  },
  'embutido': {
    biologicos: ['Clostridium botulinum (crítico)','Listeria monocytogenes','Salmonella spp.','S. aureus','E. coli STEC','Mohos toxigénicos'],
    quimicos: ['Nitrito residual','Aminas biogénicas (histamina)','Micotoxinas','Alérgenos no declarados'],
    fisicos: ['Fragmentos óseos','Fragmentos metálicos','Trozos de tripa dura']
  },
  'ahumado': {
    biologicos: ['Listeria monocytogenes','Salmonella spp.','S. aureus (si no supera 70°C centro)'],
    quimicos: ['HAPs del humo (benzo[a]pireno)','Nitrosaminas','Nitrito residual','Formaldehído'],
    fisicos: ['Astillas de madera','Ceniza']
  }
};

function hazardsForType(type){
  if(!type) return null;
  const cat = (type.category||'').toLowerCase();
  for(const key of Object.keys(HAZARD_CATALOG)){
    if(cat.includes(key)) return { category: key, hazards: HAZARD_CATALOG[key] };
  }
  return { category: 'default', hazards: HAZARD_CATALOG['muscular'] };
}

function defaultPCCsForType(type){
  if(!type) return [];
  const cat = (type.category||'').toLowerCase();
  const hasFerm = (type.stages||[]).some(s=>s.kind==='Fermentado');
  const hasAhumado = (type.stages||[]).some(s=>s.kind==='Ahumado');
  const pccs = [];
  // PCC 1: receiving core T
  pccs.push({
    id: 'pcc-recep', label: 'Recepción core T ≤ 4°C',
    stage: 'Recepción', metric: 'coreT', op: '<=', value: 4,
    severity: 'critical', hazard: 'Crecimiento mesófilos pre-cura'
  });
  // PCC 2: aw target
  const awLim = (type && typeof type.awTarget==='number' && type.awTarget>0) ? type.awTarget : (cat.includes('embutido') ? AW_TARGET_BY_CATEGORY.embutido : AW_TARGET_BY_CATEGORY.default);
  pccs.push({
    id: 'pcc-aw', label: `aw final ≤ ${awLim}`,
    stage: 'Final', metric: 'aw', op: '<=', value: awLim,
    severity: 'critical', hazard: 'Agua libre para patógenos'
  });
  // PCC 3: Fermentación pH drop (only if type has fermentation)
  if(hasFerm){
    pccs.push({
      id: 'pcc-ferm-ph', label: 'Fermentación: pH ≤ 5.3 en 48h',
      stage: 'Fermentado', metric: 'phDropHours', op: '<=', value: 48,
      severity: 'critical', hazard: 'C. botulinum / S. aureus (ventana)'
    });
  }
  // PCC 4: Ahumado core T (if applies, for cold smoke) — informational only
  if(hasAhumado){
    pccs.push({
      id: 'pcc-ahum-t', label: 'Ahumado: T superficie ≤ límite del método',
      stage: 'Ahumado', metric: 'smokeTemp', op: '<=', value: 30,
      severity: 'warning', hazard: 'HAPs del humo (ahumado alto)'
    });
  }
  return pccs;
}

function pccsForType(type){
  if(!type) return [];
  if(Array.isArray(type.haccpPCCs) && type.haccpPCCs.length > 0) return type.haccpPCCs;
  return defaultPCCsForType(type);
}

function evaluateHaccp(b){
  const type = db.types.find(t=>t.id===b.typeId);
  const pccs = pccsForType(type);
  const results = pccs.map(pcc=>{
    let status = 'pending', detail = '', measured = null;
    switch(pcc.metric){
      case 'coreT': {
        const t = b.receiving?.coreT;
        if(t === null || t === undefined){ status = 'pending'; detail = 'Sin core T registrada'; }
        else { measured = t; status = (t <= pcc.value) ? 'pass' : 'fail'; detail = `${t}°C ${pcc.op} ${pcc.value}°C`; }
        break;
      }
      case 'aw': {
        // Peor aw entre piezas (medido si existe, si no estimado) — sin recursión con safetyStatus
        const anyLogged = b.pieces.some(p => (p.weightLogs||[]).length > 0 || awReadings(p).length > 0);
        const allStagesDone = (b.stages||[]).every(s=>s.done);
        if(!anyLogged){ status='pending'; detail = 'Sin registros de peso aún'; break; }
        const sts = b.pieces.map(p=>({ p, st: pieceAwState(b, p) })).filter(x=>x.st.aw !== null);
        if(sts.length === 0){ status = 'pending'; detail = 'Sin aws calculables'; }
        else {
          const worst = sts.reduce((a,x)=> x.st.aw > a.st.aw ? x : a);
          const worstAw = worst.st.aw;
          measured = worstAw;
          const src = `${worst.p.code||'pieza'}`;
          const tx = awTxt(worst.st);
          if(worstAw <= pcc.value){ status='pass'; detail = `${src}: aw ${tx} ≤ ${pcc.value.toFixed(2)}`; }
          else if(!allStagesDone){ status='pending'; detail = `${src}: aw ${tx} · en proceso, aún faltan etapas`; }
          else if(worstAw <= pcc.value + 0.01){ status='warn'; detail = `${src}: aw ${tx} apenas sobre ${pcc.value.toFixed(2)}`; }
          else { status='fail'; detail = `${src}: aw ${tx} > ${pcc.value.toFixed(2)} con todas las etapas terminadas`; }
        }
        break;
      }
      case 'phDropHours': {
        // Did pH drop below 5.3 within pcc.value hours of fermentation start?
        const fermStage = (b.stages||[]).find(s=>s.kind==='Fermentado' && s.startedAt);
        if(!fermStage){ status = 'pending'; detail = 'Sin etapa de Fermentado'; break; }
        const start = new Date(fermStage.startedAt).getTime();
        const phLogs = (b.phLogs||[]).filter(l=>l.stageKind==='Fermentado').sort((a,b)=>new Date(a.date)-new Date(b.date));
        const okLog = phLogs.find(l=> l.ph <= 5.3 && (new Date(l.date).getTime() - start)/(1000*60*60) <= pcc.value);
        const hoursSinceStart = (Date.now() - start)/(1000*60*60);
        if(okLog){
          const hrs = (new Date(okLog.date).getTime() - start)/(1000*60*60);
          measured = hrs; status = 'pass'; detail = `pH ${okLog.ph} alcanzado en ${hrs.toFixed(1)}h`;
        } else if(hoursSinceStart >= pcc.value){
          status = 'fail'; detail = `${hoursSinceStart.toFixed(0)}h transcurridas sin pH ≤ 5.3 — riesgo botulismo`;
        } else {
          status = 'pending'; detail = `${hoursSinceStart.toFixed(0)}h / ${pcc.value}h · pH pendiente de caer`;
        }
        break;
      }
      case 'smokeTemp': {
        const smokeStage = (b.stages||[]).find(s=>s.kind==='Ahumado');
        if(!smokeStage || !smokeStage.smoke){ status = 'pending'; detail = 'Sin configuración de Ahumado'; break; }
        const smokeT = smokeStage.smoke.tempC || null;
        if(smokeT === null){ status = 'pending'; detail = 'Sin T de ahumado definida'; }
        else { measured = smokeT; status = (smokeT <= pcc.value) ? 'pass' : 'warn'; detail = `${smokeT}°C ${pcc.op} ${pcc.value}°C`; }
        break;
      }
      default: status = 'pending'; detail = 'Métrica no reconocida';
    }
    // v4.3.3 — una desviación documentada (resuelta o bajo monitoreo) deja de bloquear;
    // «descartado» o «pendiente» siguen bloqueando.
    let dev = null;
    if(status === 'fail'){
      dev = (b.deviations||[]).filter(d=>d.pccId===pcc.id).sort((x,y)=>new Date(y.ts)-new Date(x.ts))[0] || null;
      if(dev && (dev.outcome==='resolved' || dev.outcome==='monitoring' || dev.outcome==='accepted')){
        status = 'doc';
        detail += dev.outcome==='accepted'
          ? ` · aceptado manualmente por el productor: ${dev.description}`
          : ` · desviación ${dev.outcome==='resolved'?'resuelta':'bajo monitoreo'}: ${dev.action||dev.description}`;
      }
    }
    return { pcc, status, detail, measured, dev };
  });
  const summary = {
    total: results.length,
    pass: results.filter(r=>r.status==='pass').length,
    warn: results.filter(r=>r.status==='warn').length,
    fail: results.filter(r=>r.status==='fail').length,
    pending: results.filter(r=>r.status==='pending').length,
    documented: results.filter(r=>r.status==='doc').length,
    accepted: results.filter(r=>r.status==='doc' && r.dev && r.dev.outcome==='accepted').length,
    criticalFails: results.filter(r=>r.status==='fail' && r.pcc.severity==='critical').length
  };
  return { results, summary };
}

function recordDeviation(batchId, data){
  const b = db.batches.find(x=>x.id===batchId);
  if(!b) return;
  if(!b.deviations) b.deviations = [];
  b.deviations.push({
    id: uid('dev'),
    ts: new Date().toISOString(),
    pccId: data.pccId || null,
    pccLabel: data.pccLabel || '',
    description: data.description || '',
    action: data.action || '',
    outcome: data.outcome || 'open',
    author: 'operador'
  });
  saveDB();
}

function diffusivitySaltMeat({tempC=5, fatPct=20}){
  const Dref = 3.0e-10; // m²/s at 5°C
  const Q10 = 1.5;
  const Dt = Dref * Math.pow(Q10, (tempC - 5) / 10);
  const fatFrac = Math.max(0, Math.min(0.6, (fatPct||20) / 100));
  const Dfat = Dt * (1 - 0.6 * fatFrac);
  return Math.max(1e-11, Dfat);
}

function fickSaltPenetrationDays({thicknessCm, shape='tubular', tempC=5, fatPct=20}){
  if(!thicknessCm || thicknessCm <= 0) return null;
  const L = (thicknessCm/2) / 100; // meters
  const D = diffusivitySaltMeat({tempC, fatPct});
  // Shape factor: cylinder slightly slower than flat (longer center distance)
  const shapeFactor = (shape === 'flat') ? 1.0 : 1.15;
  const seconds = 3 * shapeFactor * (L*L) / (Math.PI * Math.PI * D);
  return seconds / 86400; // days
}

function evaluateFickSalt(nb, type){
  const typeStage = (type?.stages||[]).find(s=>s.kind==='Curado');
  const daysConfigured = typeStage?.dEst || null;
  if(!daysConfigured || !nb.pieces?.length) return null;
  const maxThickness = Math.max(...nb.pieces.map(p=>+p.thickness||0), 1);
  const shape = nb.pieces[0]?.shape || 'tubular';
  const tempC = typeStage?.env?.T ?? 5;
  const fatPct = type?.fatPct ?? 20; // default lean estimation
  const daysNeeded = fickSaltPenetrationDays({ thicknessCm: maxThickness, shape, tempC, fatPct });
  if(!daysNeeded) return null;
  const ratio = daysConfigured / daysNeeded;
  let status, msg;
  if(ratio >= 1.3){ status='excess'; msg = `Curado configurado (${daysConfigured}d) excede ampliamente Fick (${daysNeeded.toFixed(0)}d) — considera reducir`; }
  else if(ratio >= 1.0){ status='ok'; msg = `Curado ${daysConfigured}d ≥ Fick ${daysNeeded.toFixed(0)}d · penetración al centro OK`; }
  else if(ratio >= 0.85){ status='warn'; msg = `Curado ${daysConfigured}d está marginal · Fick sugiere ${daysNeeded.toFixed(0)}d para completa penetración`; }
  else { status='fail'; msg = `⚠ Curado ${daysConfigured}d insuficiente · Fick predice ${daysNeeded.toFixed(0)}d para alcanzar el centro`; }
  return { daysNeeded, daysConfigured, status, ratio, msg, maxThickness, tempC };
}

function diffusivitySmoke({tempC=25}){
  const Dref = 2e-10; // effective, at 20°C
  const Q10 = 1.8;
  return Dref * Math.pow(Q10, (tempC-20)/10);
}

function erfApprox(x){
  // Abramowitz & Stegun 7.1.26 approximation
  const sign = Math.sign(x);
  x = Math.abs(x);
  const a1= 0.254829592, a2=-0.284496736, a3=1.421413741, a4=-1.453152027, a5=1.061405429, p=0.3275911;
  const t = 1 / (1 + p*x);
  const y = 1 - (((((a5*t + a4)*t) + a3)*t + a2)*t + a1)*t * Math.exp(-x*x);
  return sign * y;
}

function fickSmokeProfile({thicknessCm, tempC=25, hours=6}){
  if(!thicknessCm || !hours) return null;
  const D = diffusivitySmoke({tempC});
  const tSec = hours * 3600;
  const halfMm = (thicknessCm/2) * 10;
  const points = [];
  for(let depthMm = 0; depthMm <= halfMm; depthMm += Math.max(1, halfMm/8)){
    const x = depthMm / 1000; // m
    // semi-infinite 1D (reasonable for depth << half-thickness)
    const sat = (depthMm === 0) ? 100 : (1 - erfApprox(x / (2*Math.sqrt(D*tSec)))) * 100;
    points.push({ depthMm: Math.round(depthMm), saturationPct: Math.max(0, Math.min(100, sat)) });
  }
  if(points[points.length-1].depthMm < halfMm){
    const x = halfMm/1000;
    const sat = (1 - erfApprox(x / (2*Math.sqrt(D*tSec)))) * 100;
    points.push({ depthMm: Math.round(halfMm), saturationPct: Math.max(0, Math.min(100, sat)) });
  }
  return points;
}

function predictProfile(type, batchYield, opts){
  const yieldFinal = batchYield ?? type?.yield?.target ?? 60;
  // Average salt % across Curado stages
  let saltPct = 0;
  (type?.stages||[]).forEach(s=>{
    if(s.brine?.saltPct) saltPct += s.brine.saltPct;
  });
  if(saltPct === 0) saltPct = 2.8;
  // Sugar % (approx): any recipe ingredient flagged as sugar
  let sugarPct = 0;
  (type?.stages||[]).forEach(s=>{
    (s.recipe||[]).forEach(r=>{
      const ing = (db.ingredients||[]).find(i=>i.name===r.ingredient);
      if(ing && (ing.category === 'azucar')){
        sugarPct += (+r.amount || 0) / 1000; // amount in g/kg → %
      }
    });
  });
  // Fermented?
  const hasFerm = (type?.stages||[]).some(s=>s.kind==='Fermentado');
  // Smoked?
  const hasSmoke = (type?.stages||[]).some(s=>s.kind==='Ahumado');
  // Total days (sum of dEst)
  const daysTotal = (type?.stages||[]).reduce((s,st)=>s+(st.dEst||0),0);
  // Average cava T estimate (default 13 if not specified in any stage)
  let avgT = 13;
  // concentration factor: salt in final = salt_added / yield_fraction
  const concFactor = 100 / Math.max(30, yieldFinal);
  const saltFinal = saltPct * concFactor;
  // Scores (0-10)
  const salado = Math.min(10, Math.max(0, saltFinal * 1.6)); // ~2.8%→4.5 ingoing × conc → ~7-8
  const umami = Math.min(10, Math.max(0, 3 + 0.03 * daysTotal + (hasFerm?1.5:0)));
  const dulce = Math.min(10, Math.max(0, sugarPct * 2.5 + (daysTotal>120?1:0)));
  const acido = Math.min(10, Math.max(0, hasFerm ? 5 + 0.01*daysTotal : 1));
  const firmeza = Math.min(10, Math.max(0, (100 - yieldFinal) * 0.18)); // 40% loss → 7.2
  const ahumado = hasSmoke ? Math.min(10, 3 + ((type?.stages||[]).find(s=>s.kind==='Ahumado')?.smoke?.hours || 0) * 0.3) : 0;
  const out = { salado, umami, dulce, acido, firmeza, ahumado,
    _meta: { saltPct, sugarPct, hasFerm, hasSmoke, daysTotal, yieldFinal, saltFinal, calibrated:false } };
  // Calibración por catas reales (type.tasteBias). opts.raw = predicción sin corregir.
  if(!opts?.raw && type?.tasteBias){
    Object.entries(type.tasteBias).forEach(([k,v])=>{
      if(out[k]!=null){ out[k] = Math.min(10, Math.max(0, out[k] + v)); out._meta.calibrated = true; }
    });
  }
  return out;
}

function compareProfile(type, batch){
  const pred = predictProfile(type, batch?.targetYield);
  if(!batch?.tasting) return { predicted: pred, tasted: null };
  const t = batch.tasting;
  // Tasting uses 0-5 for dulce/salado/umami/amargo/acido — scale to 0-10
  // Escala nueva (esc:2): 1..5 → 0..10 con 3 (balanceado) = 5. Escala anterior: 0..5 → ×2.
  const lv = k => t[k]==null ? 0 : (t.esc===2 ? (t[k]-1)*2.5 : t[k]*2);
  const tasted = {
    salado: lv('salado'), umami: lv('umami'), dulce: lv('dulce'), acido: lv('acido'),
    firmeza: (t.textura ?? 0) * 2
  };
  return { predicted: pred, tasted };
}

function proteolysisIndex({avgTempC, days}){
  if(!avgTempC || !days || days <= 0) return null;
  const factor = Math.pow(2, (avgTempC - 15) / 10);
  const idx = (days * factor / 365) * 100;
  return {
    index: idx,
    factor,
    label: idx < 20 ? 'muy baja (textura firme, poca complejidad)' :
           idx < 40 ? 'baja (textura firme, aroma simple)' :
           idx < 70 ? 'media (bresaola / lomo típico)' :
           idx < 100 ? 'alta (madurada compleja)' :
           idx < 150 ? 'muy alta (prosciutto largo)' :
           'extrema (jamón ibérico añejo)'
  };
}

function batchProteolysis(b){
  const stageDays = (b.stages||[]).reduce((s,st)=>{
    if(st.kind==='Secado' || st.kind==='Madurado' || st.kind==='Balanceo'){
      const start = st.startedAt ? new Date(st.startedAt).getTime() : null;
      const end = st.actualEnd ? new Date(st.actualEnd).getTime() : (st.expectedEnd ? new Date(st.expectedEnd).getTime() : null);
      if(start && end) return s + (end-start)/86400000;
    }
    return s;
  }, 0);
  if(stageDays <= 0) return null;
  const env = (typeof envStats === 'function') ? envStats(b) : null;
  const avgT = env?.avgT ?? 13;
  return proteolysisIndex({ avgTempC: avgT, days: stageDays });
}

