const FLAVOR_AXES = [
  {k:'dulce',label:'Dulce',adj:['dulce','poco dulce','demasiado dulce']},
  {k:'salado',label:'Salado',adj:['sal','poca sal','demasiada sal']},
  {k:'umami',label:'Umami',adj:['umami','poco umami','demasiado umami']},
  {k:'amargo',label:'Amargo',adj:['amargor','poco amargor','demasiado amargor']},
  {k:'acido',label:'Ácido',adj:['acidez','poca acidez','demasiada acidez']}
];

function flavorDiag(inten){
  if(inten==null) return null;
  return inten===3 ? 'ok' : inten<3 ? 'poco' : 'mucho';
}

function flavorVerdict(v, q){
  if(v==null) return null;
  const dir = flavorDiag(v);
  if(q==null) return { state: dir==='ok'?'ok':'sinq', dir };
  if(q>=4) return { state:'ok', dir };
  if(q===3) return { state:'mejorable', dir };
  return { state:'problema', dir };
}

function flavorVal(t,k){ return (t && t.esc===2 && t[k]!=null) ? t[k] : null; }

const DEFECT_SEV = { 1:'Leve', 2:'Moderado', 3:'Grave' };

function tastingList(b){
  if(!b) return [];
  if(!Array.isArray(b.tastings)){
    b.tastings = b.tasting ? [Object.assign({ id: uid('cat') }, b.tasting)] : [];
  }
  b.tastings.forEach(t=>{ if(!t.id) t.id = uid('cat'); });
  return b.tastings.slice().sort((x,y)=> String(x.fecha||'').localeCompare(String(y.fecha||'')));
}

function syncLatestTasting(b){
  const l = tastingList(b);
  b.tasting = l.length ? l[l.length-1] : null;
}

function migrateTastings(){
  (db.batches||[]).forEach(b=>{ if(b.tasting || Array.isArray(b.tastings)){ tastingList(b); syncLatestTasting(b); } });
}

function tastingDays(b, fecha){
  if(!b?.startedAt || !fecha) return null;
  const d = Math.round((new Date(fecha+'T12:00:00') - new Date(b.startedAt)) / 86400000);
  return isFinite(d) ? Math.max(0, d) : null;
}

function tastingDefects(t){ return (t?.defectos||[]).filter(d=>d && d.sev>0); }

function batchScore(b){
  const l = tastingList(b).filter(t=>t.notaGlobal!=null);
  return l.length ? l[l.length-1].notaGlobal : null;
}

function tastedBatches(typeId){
  return db.batches.filter(b=> b.typeId===typeId && b.status!=='discarded' && tastingList(b).length>0);
}

function optimalWindow(typeId){
  const pts = [];
  tastedBatches(typeId).forEach(b=> tastingList(b).forEach(t=>{
    const d = t.dias ?? tastingDays(b, t.fecha);
    if(t.notaGlobal!=null && d!=null) pts.push({ d, n:t.notaGlobal });
  }));
  if(pts.length < 3) return null;
  const bins = {};
  pts.forEach(p=>{ const k = Math.floor(p.d/30); (bins[k] = bins[k]||[]).push(p.n); });
  const rows = Object.entries(bins).map(([k,a])=>({
    from:+k*30, to:+k*30+29, n:a.length, avg:a.reduce((s,v)=>s+v,0)/a.length
  })).sort((x,y)=>x.from-y.from);
  if(rows.length < 2) return { rows, best:rows[0], total:pts.length, weak:true };
  const best = rows.reduce((m,r)=> r.avg>m.avg || (r.avg===m.avg && r.n>m.n) ? r : m, rows[0]);
  return { rows, best, total:pts.length, weak:false };
}

const BIAS_AXES = ['salado','umami','dulce','acido'];

function modelBias(typeId){
  const type = db.types.find(t=>t.id===typeId); if(!type) return null;
  const acc = {}; BIAS_AXES.forEach(a=>acc[a]=[]);
  let n = 0;
  tastedBatches(typeId).forEach(b=>{
    const t = tastingList(b).slice(-1)[0]; if(!t) return;
    const pred = predictProfile(type, b.targetYield, { raw:true });
    // Solo catas con escala nueva: 1..5 → 0..10, con 3 (balanceado) = 5.
    let used = false;
    BIAS_AXES.forEach(a=>{ const v = flavorVal(t,a); if(v!=null){ acc[a].push((v-1)*2.5 - (pred[a]||0)); used = true; } });
    if(used) n++;
  });
  if(n < 2) return { n, bias:null };
  const bias = {};
  BIAS_AXES.forEach(a=>{ if(acc[a].length>=2) bias[a] = acc[a].reduce((s,v)=>s+v,0)/acc[a].length; });
  return { n, bias };
}

function applyModelBias(typeId){
  const type = db.types.find(t=>t.id===typeId); if(!type) return;
  const mb = modelBias(typeId);
  if(!mb?.bias){ toast('Faltan catas para calibrar'); return; }
  type.tasteBias = {};
  Object.entries(mb.bias).forEach(([k,v])=>{ type.tasteBias[k] = Math.round(v*10)/10; });
  saveDB(); render(); toast('Modelo calibrado para '+type.name);
}

function clearModelBias(typeId){
  const type = db.types.find(t=>t.id===typeId); if(!type) return;
  delete type.tasteBias; saveDB(); render(); toast('Calibración quitada');
}

function typeQuality(typeId){
  const bs = tastedBatches(typeId);
  const scores = bs.map(batchScore).filter(v=>v!=null);
  const defCount = {};
  let withDef = 0;
  bs.forEach(b=>{
    const names = new Set();
    tastingList(b).forEach(t=> tastingDefects(t).forEach(d=> names.add(d.name)));
    if(names.size) withDef++;
    names.forEach(n=> defCount[n] = (defCount[n]||0)+1);
  });
  const top = Object.entries(defCount).sort((a,b)=>b[1]-a[1])[0] || null;
  return {
    nBatches: bs.length,
    nTastings: bs.reduce((s,b)=>s+tastingList(b).length,0),
    avg: scores.length ? scores.reduce((s,v)=>s+v,0)/scores.length : null,
    defRate: bs.length ? withDef/bs.length : null,
    topDefect: top ? { name:top[0], n:top[1] } : null,
    defCount
  };
}

