const CUT_TO_INGREDIENT = {
  'cerdo-magro':      'Cerdo magro (cañón/lomo/pernil)',
  'cerdo-grasa-pura': 'Grasa de cerdo pura (manteca/papada limpia)',
  'res-magra':        'Res magra (bola/solomo)',
  'pato-magret':      'Pato magret magro (pechuga desgrasada)'
};

const MEAT_CUTS = Object.fromEntries(Object.entries(CUT_TO_INGREDIENT).map(([k,n])=>[k, { label:n, ...MEAT_NUTR_SEEDS[n] }]));

const MEAT_PROFILES = MEAT_CUTS;

function meatIngredients(){
  return (db.ingredients||[]).filter(i=>i.category==='carne').sort((a,b)=>a.name.localeCompare(b.name,'es'));
}

function meatNutrFor(name){
  const ing = (db.ingredients||[]).find(i=>i.name===name && i.category==='carne');
  if(ing?.nutr) return ing.nutr;
  if(MEAT_NUTR_SEEDS[name]) return MEAT_NUTR_SEEDS[name];
  return null;
}

function normalizeComposition(composition){
  if(!composition) return composition;
  return composition.map(c=>{
    if(c.ingredient) return c;
    if(c.cut && CUT_TO_INGREDIENT[c.cut]) return { ingredient: CUT_TO_INGREDIENT[c.cut], pct: c.pct, note: c.note||'' };
    return c;
  });
}

function mixMeats(composition){
  if(!composition || !composition.length) return null;
  const comp = normalizeComposition(composition);
  const totalPct = comp.reduce((s,c)=>s + (+c.pct||0), 0);
  if(totalPct <= 0) return null;
  const profile = { kcal:0, protein:0, fat:0, satFat:0, transFat:0, carbs:0, sugars:0, fiber:0, sodium_mg:0, cholesterol:0, water:0 };
  const parts = [];
  comp.forEach(c=>{
    const nutr = meatNutrFor(c.ingredient);
    if(!nutr) return;
    const w = (+c.pct||0) / totalPct;
    for(const k of Object.keys(profile)){ profile[k] += (nutr[k]||0) * w; }
    const formTxt = c.form==='molido' ? ' molido' : c.form==='picado' ? ' picado' : '';
    parts.push(`${(+c.pct).toFixed(c.pct%1?1:0)}% ${c.ingredient}${formTxt}${c.note?' ('+c.note+')':''}`);
  });
  profile.label = parts.join(' + ');
  profile.composition = comp;
  return profile;
}

function ingredientNutrition(name){
  const n = (name||'').toLowerCase();
  // Salts (NaCl ~ 39.3% Na, so 100g salt = 39342 mg Na)
  if(/sal.*maldon|sal.*marina|sal.*mesa|kosher|sal rosada|sal.*himalaya|diamond crystal|morton kosher/.test(n)){
    return { kcal:0, protein:0, fat:0, satFat:0, transFat:0, carbs:0, sugars:0, fiber:0, sodium_mg:38758, water:0 };
  }
  // Cure salts: InstaCure #1 (93.75% NaCl) and #2 (89.75% NaCl)
  if(/instacure #1|cura #1|pink salt #1/.test(n)){
    return { kcal:0, protein:0, fat:0, satFat:0, transFat:0, carbs:0, sugars:0, fiber:0, sodium_mg:36355, water:0 }; // 93.75% × 38758
  }
  if(/instacure #2|cura #2|pink salt #2/.test(n)){
    return { kcal:0, protein:0, fat:0, satFat:0, transFat:0, carbs:0, sugars:0, fiber:0, sodium_mg:34785, water:0 }; // 89.75% × 38758
  }
  // Sugars
  if(/dextrosa|glucosa/.test(n)){
    return { kcal:400, protein:0, fat:0, satFat:0, transFat:0, carbs:100, sugars:100, fiber:0, sodium_mg:0, water:0 };
  }
  if(/^sugar$|azúcar|sacarosa|turbinado/.test(n)){
    return { kcal:387, protein:0, fat:0, satFat:0, transFat:0, carbs:100, sugars:100, fiber:0, sodium_mg:1, water:0 };
  }
  // Spices (per 100g — but usage is ~0.1-0.5g per 100g final, so negligible contribution)
  if(/pepper|pimienta/.test(n)){
    return { kcal:251, protein:10.4, fat:3.3, satFat:1.4, transFat:0, carbs:64, sugars:0.6, fiber:25, sodium_mg:20, water:12 };
  }
  if(/paprika|pimentón/.test(n)){
    return { kcal:282, protein:14.1, fat:12.9, satFat:2.1, transFat:0, carbs:54, sugars:10.3, fiber:35, sodium_mg:68, water:12 };
  }
  if(/ajo|garlic/.test(n)){
    return { kcal:331, protein:16.5, fat:0.7, satFat:0.1, transFat:0, carbs:73, sugars:2.4, fiber:9, sodium_mg:60, water:6 };
  }
  if(/vino|wine/.test(n)){
    return { kcal:83, protein:0.1, fat:0, satFat:0, transFat:0, carbs:2.6, sugars:0.6, fiber:0, sodium_mg:4, water:86 };
  }
  // Cultures, molds, additives — negligible mass/nutrition
  if(/mold|starter|flavor of italy|lhp|penicillium|lactobacillus|culture|cultivo/.test(n)){
    return null; // explicitly negligible
  }
  // Default: unknown — return null (user can override via ingredient edit)
  return null;
}

function baseMeatForType(type){
  const fallback = { label:'Carne genérica', ...MEAT_NUTR_SEEDS['Cerdo magro (cañón/lomo/pernil)'] };
  if(!type) return fallback;
  if(type.baseMeat?.composition){
    const mixed = mixMeats(type.baseMeat.composition);
    if(mixed) return mixed;
  }
  if(type.baseMeat && typeof type.baseMeat === 'object' && type.baseMeat.kcal !== undefined && !type.baseMeat.composition){
    return type.baseMeat;
  }
  return fallback;
}

const BASE_MEAT_COMPOSITIONS = {
  'Lomo Español': [{ingredient:'Cerdo magro (cañón/lomo/pernil)', pct:100, note:'cañón', form:'entero'}]
};

function migrateMeatIngredients(){
  if(!db.ingredients) db.ingredients = [];
  let touched = false;
  db.ingredients.forEach(ing=>{
    if(ing.category !== 'carne') return;
    const seed = MEAT_NUTR_SEEDS[ing.name];
    if(!seed) return; // carne propia del usuario sin semilla conocida — no tocar
    if(!ing.nutr){ ing.nutr = {...seed}; touched = true; }
    if(!ing.meat && MEAT_META_SEEDS[ing.name]){ ing.meat = {...MEAT_META_SEEDS[ing.name]}; touched = true; }
  });
  if(touched){ try{ localStorage.setItem(LS_KEY, JSON.stringify(db)); }catch(e){} }
}

function migrateBaseMeat(){
  migrateMeatIngredients(); // solo parcha carnes existentes, no crea nada
  let touched = false;
  (db.types||[]).forEach(t=>{
    const spec = BASE_MEAT_COMPOSITIONS[t.name];
    if(spec && !t.baseMeat?.composition){
      t.baseMeat = { composition: JSON.parse(JSON.stringify(spec)) };
      touched = true;
    } else if(t.baseMeat?.composition){
      // Normaliza legacy {cut:} → {ingredient:}
      const norm = normalizeComposition(t.baseMeat.composition);
      if(JSON.stringify(norm) !== JSON.stringify(t.baseMeat.composition)){
        t.baseMeat.composition = norm;
        touched = true;
      }
    }
  });
  if(touched){ try{ localStorage.setItem(LS_KEY, JSON.stringify(db)); }catch(e){} }
}

function computeNutrition(type, overrideYield){
  if(!type) return null;
  const greenG = 1000; // reference 1 kg of green meat for calculation
  const yieldPct = overrideYield ?? type.yield?.target ?? 60;
  const finalG = greenG * yieldPct / 100;
  if(finalG <= 0) return null;

  const meat = baseMeatForType(type);
  const totals = { kcal:0, protein:0, fat:0, satFat:0, transFat:0, carbs:0, sugars:0, fiber:0, sodium_mg:0 };
  // Add base meat contribution
  for(const k of Object.keys(totals)) totals[k] += greenG * (meat[k]||0) / 100;

  // Walk all stages' recipes and brines
  (type.stages||[]).forEach(s=>{
    (s.recipe||[]).forEach(r=>{
      // Recipe amounts are typically g per kg of green meat; scale to greenG
      const grams = (+r.amount || 0) * (greenG/1000);
      const prof = ingredientNutrition(r.ingredient);
      if(!prof) return;
      for(const k of Object.keys(totals)) totals[k] += grams * (prof[k]||0) / 100;
    });
    // Brine: salt and cure salt
    if(s.brine){
      if(s.brine.saltPct && s.brine.saltIngredient){
        const saltG = greenG * s.brine.saltPct / 100;
        const prof = ingredientNutrition(s.brine.saltIngredient);
        if(prof) for(const k of Object.keys(totals)) totals[k] += saltG * (prof[k]||0) / 100;
      }
      if(s.brine.cureSalt?.ingredient && s.brine.cureSalt.gPerKg){
        const cureG = s.brine.cureSalt.gPerKg * (greenG/1000);
        const prof = ingredientNutrition(s.brine.cureSalt.ingredient);
        if(prof) for(const k of Object.keys(totals)) totals[k] += cureG * (prof[k]||0) / 100;
      }
    }
  });

  // Normalize to per-100g of final product
  const per100g = {};
  for(const k of Object.keys(totals)) per100g[k] = totals[k] * 100 / finalG;

  // Per serving (default 30g)
  const servingG = type.servingG || 30;
  const perServing = {};
  for(const k of Object.keys(per100g)) perServing[k] = per100g[k] * servingG / 100;

  // Compute salt (g) from sodium (mg): salt = Na × 2.5 (for EU/comparison)
  per100g.salt = (per100g.sodium_mg * 2.5) / 1000; // g
  perServing.salt = (perServing.sodium_mg * 2.5) / 1000;

  // Compute kcal from macros if the direct sum is zero (sanity): kcal = 4*(protein+carbs) + 9*fat
  if(per100g.kcal === 0 && (per100g.protein > 0 || per100g.fat > 0)){
    per100g.kcal = 4*(per100g.protein + per100g.carbs) + 9*per100g.fat;
    perServing.kcal = per100g.kcal * servingG / 100;
  }
  per100g.kJ = per100g.kcal * 4.184;
  perServing.kJ = perServing.kcal * 4.184;

  // Colombia frontal warnings (Resolución 810/2492 — productos sólidos, umbrales por 100g)
  const warnings = [];
  if(per100g.sodium_mg >= 400) warnings.push({ kind:'sodio', label:'ALTO EN\nSODIO' });
  if(per100g.satFat >= 4)      warnings.push({ kind:'satFat', label:'ALTO EN\nGRASAS\nSATURADAS' });
  if(per100g.sugars >= 10)     warnings.push({ kind:'azucares', label:'ALTO EN\nAZÚCARES' });

  // Allergens auto-detected from ingredient names
  const allergens = [];
  (type.stages||[]).forEach(s=>{
    (s.recipe||[]).forEach(r=>{
      const nm = (r.ingredient||'').toLowerCase();
      if(/leche|lacteo|lactosa|queso|suero/.test(nm)) allergens.push('Lácteos');
      if(/trigo|harina|gluten|cebada|centeno|avena/.test(nm)) allergens.push('Gluten');
      if(/soja|soya/.test(nm)) allergens.push('Soja');
      if(/mostaza/.test(nm)) allergens.push('Mostaza');
      if(/apio/.test(nm)) allergens.push('Apio');
      if(/sulfito|sulfite/.test(nm)) allergens.push('Sulfitos');
      if(/huevo|egg/.test(nm)) allergens.push('Huevo');
    });
  });

  // Additives to declare (nitritos, nitratos)
  const additives = [];
  (type.stages||[]).forEach(s=>{
    if(s.brine?.cureSalt?.ingredient){
      const nm = s.brine.cureSalt.ingredient.toLowerCase();
      if(/instacure #1|cura #1/.test(nm)){
        additives.push('Conservante: nitrito de sodio (INS 250)');
      }
      if(/instacure #2|cura #2/.test(nm)){
        additives.push('Conservantes: nitrito de sodio (INS 250), nitrato de sodio (INS 251)');
      }
    }
  });

  return {
    per100g, perServing, servingG, finalG, greenG, yieldPct,
    baseMeat: meat,
    warnings,
    allergens: [...new Set(allergens)],
    additives: [...new Set(additives)]
  };
}

function labelIngredientList(type){
  if(!type) return [];
  const greenG = 1000;
  const items = [{ name: baseMeatForType(type).label, mass: greenG, isMeat: true }];
  (type.stages||[]).forEach(s=>{
    if(s.brine?.saltPct && s.brine.saltIngredient){
      items.push({ name: s.brine.saltIngredient, mass: greenG * s.brine.saltPct / 100 });
    }
    if(s.brine?.cureSalt?.ingredient && s.brine.cureSalt.gPerKg){
      items.push({ name: s.brine.cureSalt.ingredient, mass: s.brine.cureSalt.gPerKg });
    }
    (s.recipe||[]).forEach(r=>{
      items.push({ name: r.ingredient, mass: (+r.amount||0) });
    });
  });
  // Merge duplicates
  const merged = {};
  items.forEach(i=>{
    if(!merged[i.name]) merged[i.name] = { name:i.name, mass:0, isMeat:i.isMeat };
    merged[i.name].mass += i.mass;
  });
  return Object.values(merged).sort((a,b)=>b.mass - a.mass);
}

const VD = {
  fat: 65,          // g
  satFat: 20,       // g
  cholesterol: 300, // mg (asumido para charcutería ~70 mg/100g)
  sodium_mg: 2000,  // mg
  carbs: 300,       // g
  fiber: 25,        // g
  addedSugar: 50,   // g
  protein: 50       // g
};

function pctVD(amount, ref){
  if(!ref || !amount) return 0;
  return Math.round(100 * amount / ref);
}

function requiredSellos(type){
  const n = computeNutrition(type);
  if(!n) return [];
  const list = [];
  if(n.per100g.sodium_mg >= 400) list.push('sodio');
  if(n.per100g.satFat    >= 4)   list.push('grasasSaturadas');
  if(n.per100g.transFat  >= 1)   list.push('grasasTrans');
  if(n.per100g.sugars    >= 10)  list.push('azucares');
  // Edulcorantes: scan ingredients
  const hasEdulcorante = (type.stages||[]).some(s=>
    (s.recipe||[]).some(r=>/edulcorante|aspartam|sucralosa|stevia|acesulfam|sacarina|xilitol|eritritol|sorbitol/i.test(r.ingredient||''))
  );
  if(hasEdulcorante) list.push('edulcorantes');
  return list;
}

const SELLO_META = {
  sodio:            { title:'EXCESO EN SODIO',             fname:'sello_exceso_sodio' },
  grasasSaturadas:  { title:'EXCESO EN GRASAS SATURADAS',  fname:'sello_exceso_grasas_saturadas' },
  grasasTrans:      { title:'EXCESO EN GRASAS TRANS',      fname:'sello_exceso_grasas_trans' },
  azucares:         { title:'EXCESO EN AZÚCARES',          fname:'sello_exceso_azucares' },
  edulcorantes:     { title:'CONTIENE EDULCORANTES',       fname:'sello_contiene_edulcorantes' }
};

function renderSelloSVG(kind){
  const meta = SELLO_META[kind]; if(!meta) return '';
  // Unidad x · ancho 24x, con padding de x alrededor → viewBox 26x × 26x
  const x = 20;
  const W = 26*x, H = 26*x;
  // Octógono exterior: inscrito en 24x × 24x, chamfer x en cada esquina
  // Coords del octágono (origen esquina sup. izq. del cuadrado 24x × 24x, desplazado +x,+x):
  const o = x; // offset del padding
  // 8 vértices: top-left-notch, top-right-notch, right-top, right-bottom, bottom-right-notch, bottom-left-notch, left-bottom, left-top
  const pts = (shrink=0) => {
    const s = shrink;
    return [
      [o+x+s,       o+s],
      [o+23*x-s,    o+s],
      [o+24*x-s,    o+x+s],
      [o+24*x-s,    o+23*x-s],
      [o+23*x-s,    o+24*x-s],
      [o+x+s,       o+24*x-s],
      [o-s,         o+23*x-s],
      [o-s,         o+x+s]
    ].map(p=>p.join(',')).join(' ');
  };

  // Capas: 1) negro exterior, 2) blanco (banda), 3) negro interior con texto
  const outerBlack = pts(0);
  const whiteBand  = pts(0.5*x);  // reduce ~0.5x para dejar banda blanca
  const innerBlack = pts(1.2*x);  // reduce más para el octágono interior

  // Texto: dividir título en líneas
  const titleLines = meta.title.split(' ');
  // Agrupar inteligentemente: "EXCESO EN" / "SODIO" ó "EXCESO EN" / "GRASAS" / "SATURADAS"
  let lines;
  if(kind === 'sodio')               lines = ['EXCESO EN','SODIO'];
  else if(kind === 'azucares')       lines = ['EXCESO EN','AZÚCARES'];
  else if(kind === 'grasasSaturadas')lines = ['EXCESO EN','GRASAS','SATURADAS'];
  else if(kind === 'grasasTrans')    lines = ['EXCESO EN','GRASAS','TRANS'];
  else if(kind === 'edulcorantes')   lines = ['CONTIENE','EDULCORANTES'];

  // Tamaño de fuente ajustado según nº de líneas (para caber dentro del octágono negro central)
  const fontByLines = { 2: 3.1*x, 3: 2.4*x };
  const fontSize = fontByLines[lines.length];
  const lineHeight = fontSize * 1.08;

  // Centro vertical del bloque de texto: aprox centro geométrico del octágono negro (y = 12x + o)
  // pero dejando espacio para MINSALUD en la banda inferior
  const centerY = o + 11*x;
  const totalBlockH = lineHeight * lines.length;
  const firstY = centerY - totalBlockH/2 + fontSize*0.85;

  // MINSALUD label: en la banda inferior del octágono interior
  const minsaludY = o + 20.5*x;
  const minsaludFont = 1.5*x;

  const textEls = lines.map((l,i)=>
    `<text x="${o+12*x}" y="${firstY + i*lineHeight}" fill="#ffffff" font-family="'Helvetica Neue',Arial,sans-serif" font-weight="900" font-size="${fontSize}" text-anchor="middle" letter-spacing="0">${escapeHtml(l)}</text>`
  ).join('');

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" shape-rendering="geometricPrecision">
  <rect width="${W}" height="${H}" fill="#ffffff"/>
  <!-- Octágono exterior negro (borde fino) -->
  <polygon points="${outerBlack}" fill="#000000"/>
  <!-- Banda blanca -->
  <polygon points="${whiteBand}"  fill="#ffffff"/>
  <!-- Octágono interior negro (área de texto) -->
  <polygon points="${innerBlack}" fill="#000000"/>
  ${textEls}
  <text x="${o+12*x}" y="${minsaludY}" fill="#ffffff" font-family="'Helvetica Neue',Arial,sans-serif" font-weight="900" font-size="${minsaludFont}" text-anchor="middle" letter-spacing="1">MINSALUD</text>
</svg>`;
}

function renderNutritionTableSVG(type, batch, servingsPerPack){
  const n = computeNutrition(type); if(!n) return '';
  const servG = n.servingG;
  const servPerPack = +servingsPerPack || null;
  const prodName = type.name;

  const W = 600;
  // Dinámico: calcular H después, placeholder
  const pad = 20;
  const innerW = W - 2*pad;

  const fmtNum = (v, d=1) => {
    if(!isFinite(v)) return '0';
    const n = Number(v);
    return n.toLocaleString('es-CO',{minimumFractionDigits:d, maximumFractionDigits:d});
  };
  const fmtInt = v => Math.round(v||0).toLocaleString('es-CO');

  const ps = n.perServing; // por porción
  const kcalFat = Math.round(ps.fat * 9); // calorías de grasa = fat_g * 9

  // Rows: [label, value, pctVD, isSubItem, isBold]
  const rows = [
    { label:'Grasa total',          val:`${fmtNum(ps.fat,1)} g`,         vd:pctVD(ps.fat, VD.fat),           sub:false, bold:true },
    { label:'Grasas saturadas',     val:`${fmtNum(ps.satFat,1)} g`,      vd:pctVD(ps.satFat, VD.satFat),     sub:true,  bold:false },
    { label:'Grasas trans',         val:`${fmtNum(ps.transFat,1)} g`,    vd:null,                            sub:true,  bold:false },
    { label:'Colesterol',           val:`${fmtInt(ps.cholesterol || Math.round(ps.protein*3.2))} mg`, vd:pctVD((ps.cholesterol || Math.round(ps.protein*3.2)), VD.cholesterol), sub:false, bold:true },
    { label:'Sodio',                val:`${fmtInt(ps.sodium_mg)} mg`,    vd:pctVD(ps.sodium_mg, VD.sodium_mg), sub:false, bold:true },
    { divider:true },
    { label:'Carbohidratos totales',val:`${fmtNum(ps.carbs,1)} g`,       vd:pctVD(ps.carbs, VD.carbs),       sub:false, bold:true },
    { label:'Fibra dietaria',       val:`${fmtNum(ps.fiber,1)} g`,       vd:pctVD(ps.fiber, VD.fiber),       sub:true,  bold:false },
    { label:'Azúcares totales',     val:`${fmtNum(ps.sugars,1)} g`,      vd:null,                            sub:true,  bold:false },
    { label:'Azúcares añadidos',    val:`${fmtNum(ps.sugars,1)} g`,      vd:pctVD(ps.sugars, VD.addedSugar), sub:true,  bold:false, indent:true },
    { label:'Proteína',             val:`${fmtNum(ps.protein,1)} g`,     vd:null,                            sub:false, bold:true }
  ];

  // Layout vertical
  let y = pad;
  const chunks = [];

  // Border frame
  const strokeW = 1.5;

  // Título principal
  const titleFS = 30;
  chunks.push({ y, html:`<text x="${pad}" y="${y+titleFS-4}" font-family="'Helvetica Neue',Arial,sans-serif" font-weight="900" font-size="${titleFS}" fill="#000">Información nutricional</text>` });
  y += titleFS + 2;

  // Porción
  chunks.push({ y, html:`<text x="${pad}" y="${y+15}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="14" fill="#000">Tamaño de la porción ${servG} g</text>` });
  y += 20;
  if(servPerPack){
    chunks.push({ y, html:`<text x="${pad}" y="${y+15}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="14" fill="#000">Porciones por envase ${servPerPack}</text>` });
    y += 20;
  }

  // Barra negra gruesa
  const barThick = 10;
  chunks.push({ y, html:`<rect x="${pad}" y="${y+4}" width="${innerW}" height="${barThick}" fill="#000"/>` });
  y += barThick + 10;

  // "Cantidad por porción"
  chunks.push({ y, html:`<text x="${pad}" y="${y+12}" font-family="'Helvetica Neue',Arial,sans-serif" font-weight="700" font-size="12" fill="#000">Cantidad por porción</text>` });
  y += 14;

  // Separador fino
  chunks.push({ y, html:`<line x1="${pad}" y1="${y+1}" x2="${W-pad}" y2="${y+1}" stroke="#000" stroke-width="1"/>` });
  y += 4;

  // Calorías
  const calFS = 22;
  chunks.push({ y, html:`
    <text x="${pad}" y="${y+calFS-2}" font-family="'Helvetica Neue',Arial,sans-serif" font-weight="900" font-size="${calFS}" fill="#000">Calorías ${fmtInt(ps.kcal)}</text>
    <text x="${W-pad}" y="${y+calFS-6}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="13" fill="#000" text-anchor="end">Calorías de las grasas ${fmtInt(kcalFat)}</text>
  ` });
  y += calFS + 6;

  // Barra negra media
  chunks.push({ y, html:`<rect x="${pad}" y="${y}" width="${innerW}" height="6" fill="#000"/>` });
  y += 6 + 4;

  // "% de valor diario *"
  chunks.push({ y, html:`<text x="${W-pad}" y="${y+12}" font-family="'Helvetica Neue',Arial,sans-serif" font-weight="700" font-size="12" fill="#000" text-anchor="end">% de valor diario *</text>` });
  y += 14;

  // Separador fino
  chunks.push({ y, html:`<line x1="${pad}" y1="${y+1}" x2="${W-pad}" y2="${y+1}" stroke="#000" stroke-width="1"/>` });
  y += 3;

  // Filas de nutrientes
  const rowH = 22;
  const indentX = 18;
  const indent2X = 32;
  rows.forEach(r=>{
    if(r.divider){
      chunks.push({ y, html:`<line x1="${pad}" y1="${y+1}" x2="${W-pad}" y2="${y+1}" stroke="#000" stroke-width="1"/>` });
      y += 2;
      return;
    }
    const xLabel = pad + (r.indent?indent2X:(r.sub?indentX:0));
    const labelPart = r.bold
      ? `<tspan font-weight="900">${escapeHtml(r.label)}</tspan> <tspan font-weight="400">${r.val}</tspan>`
      : `${escapeHtml(r.label)} ${r.val}`;
    chunks.push({ y, html:`
      <text x="${xLabel}" y="${y+15}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="14" fill="#000">${labelPart}</text>
      ${r.vd!==null ? `<text x="${W-pad}" y="${y+15}" font-family="'Helvetica Neue',Arial,sans-serif" font-weight="900" font-size="14" fill="#000" text-anchor="end">${r.vd}%</text>` : ''}
      <line x1="${pad}" y1="${y+rowH-1}" x2="${W-pad}" y2="${y+rowH-1}" stroke="#000" stroke-width="0.5" opacity="0.5"/>
    ` });
    y += rowH;
  });

  // Barra negra inferior
  y += 2;
  chunks.push({ y, html:`<rect x="${pad}" y="${y}" width="${innerW}" height="6" fill="#000"/>` });
  y += 6 + 8;

  // Nota de %VD
  const noteFS = 11;
  const noteText = '* Los porcentajes de valores diarios están basados en una dieta de 2.000 calorías. Sus valores diarios pueden ser mayores o menores dependiendo de sus necesidades energéticas.';
  // Simple text wrap
  const words = noteText.split(' ');
  const maxCharsPerLine = 72;
  const lines = [];
  let cur = '';
  words.forEach(w=>{
    if((cur+' '+w).trim().length > maxCharsPerLine){ lines.push(cur.trim()); cur = w; }
    else cur = cur + ' ' + w;
  });
  if(cur.trim()) lines.push(cur.trim());
  lines.forEach((ln,i)=>{
    chunks.push({ y, html:`<text x="${pad}" y="${y+noteFS+2}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="${noteFS}" fill="#000">${escapeHtml(ln)}</text>` });
    y += noteFS + 3;
  });
  y += 6;

  // Ingredientes
  const ingList = labelIngredientList(type);
  const totalMass = ingList.reduce((s,i)=>s+i.mass,0);
  const ingParts = ingList.slice(0,20).map(i=>{
    const pct = totalMass>0 ? (100*i.mass/totalMass).toFixed(1) : '';
    return i.name;
  });
  const ingText = 'INGREDIENTES: ' + ingParts.join(', ') + '.';
  const ingFS = 11;
  // Wrap ingredients
  const ingWords = ingText.split(' ');
  const ingLines = [];
  let curIng = '';
  const maxIng = 75;
  ingWords.forEach(w=>{
    if((curIng+' '+w).trim().length > maxIng){ ingLines.push(curIng.trim()); curIng = w; }
    else curIng = curIng + ' ' + w;
  });
  if(curIng.trim()) ingLines.push(curIng.trim());
  ingLines.forEach(ln=>{
    chunks.push({ y, html:`<text x="${pad}" y="${y+ingFS+2}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="${ingFS}" font-weight="${ln.startsWith('INGREDIENTES')?'900':'400'}" fill="#000">${escapeHtml(ln)}</text>` });
    y += ingFS + 3;
  });
  y += 4;

  // Alérgenos
  if(n.allergens.length){
    const alText = `CONTIENE: ${n.allergens.join(', ')}.`;
    chunks.push({ y, html:`<text x="${pad}" y="${y+ingFS+2}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="${ingFS}" font-weight="900" fill="#000">${escapeHtml(alText)}</text>` });
    y += ingFS + 6;
  }

  // Aditivos
  if(n.additives.length){
    n.additives.forEach(a=>{
      chunks.push({ y, html:`<text x="${pad}" y="${y+ingFS+2}" font-family="'Helvetica Neue',Arial,sans-serif" font-size="${ingFS}" fill="#000">${escapeHtml(a)}.</text>` });
      y += ingFS + 3;
    });
    y += 4;
  }

  const totalH = y + pad;

  // Marco externo
  const frame = `<rect x="0.75" y="0.75" width="${W-1.5}" height="${totalH-1.5}" fill="none" stroke="#000" stroke-width="${strokeW}"/>`;

  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${totalH}" viewBox="0 0 ${W} ${totalH}" shape-rendering="geometricPrecision">
  <rect width="${W}" height="${totalH}" fill="#ffffff"/>
  ${frame}
  ${chunks.map(c=>c.html).join('\n')}
</svg>`;
}

function exportSVGasPNG(svgStr, filename, scale){
  if(!svgStr){ toast('No se pudo generar SVG'); return; }
  scale = scale || 2;
  // Extraer dimensiones del SVG
  const wMatch = svgStr.match(/width="(\d+(?:\.\d+)?)"/);
  const hMatch = svgStr.match(/height="(\d+(?:\.\d+)?)"/);
  const w = wMatch ? parseFloat(wMatch[1]) : 600;
  const h = hMatch ? parseFloat(hMatch[1]) : 900;

  // Data URL en lugar de blob URL (más confiable para img → canvas)
  const encoded = encodeURIComponent(svgStr).replace(/'/g,'%27').replace(/"/g,'%22');
  const dataUrl = 'data:image/svg+xml;charset=utf-8,' + encoded;

  const img = new Image();
  img.onload = ()=>{
    const canvas = document.createElement('canvas');
    canvas.width  = Math.round(w*scale);
    canvas.height = Math.round(h*scale);
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    try{
      canvas.toBlob(blob=>{
        if(!blob){ toast('Error al exportar PNG'); return; }
        const a = document.createElement('a');
        const bUrl = URL.createObjectURL(blob);
        a.href = bUrl;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(()=>URL.revokeObjectURL(bUrl), 1500);
        toast('✓ PNG descargado');
      }, 'image/png');
    }catch(e){
      console.error(e);
      toast('Error al generar PNG — intenta descargar como SVG');
    }
  };
  img.onerror = (e)=>{
    console.error('img.onerror', e);
    toast('Error al cargar SVG en imagen');
  };
  img.src = dataUrl;
}

function exportSVGFile(svgStr, filename){
  if(!svgStr){ toast('No se pudo generar SVG'); return; }
  const blob = new Blob([svgStr], {type:'image/svg+xml;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url), 1500);
  toast('✓ SVG descargado');
}

