function pearson(xs, ys){
  const n = Math.min(xs.length, ys.length);
  if(n < 3) return null;
  const pairs = [];
  for(let i=0; i<n; i++){
    if(xs[i]!==null && xs[i]!==undefined && !isNaN(xs[i]) &&
       ys[i]!==null && ys[i]!==undefined && !isNaN(ys[i])){
      pairs.push([xs[i], ys[i]]);
    }
  }
  if(pairs.length < 3) return null;
  const mx = pairs.reduce((s,[a])=>s+a,0)/pairs.length;
  const my = pairs.reduce((s,[,a])=>s+a,0)/pairs.length;
  let num=0, dx2=0, dy2=0;
  for(const [x,y] of pairs){ const dx=x-mx, dy=y-my; num+=dx*dy; dx2+=dx*dx; dy2+=dy*dy; }
  if(dx2===0 || dy2===0) return null;
  return { r: num / Math.sqrt(dx2*dy2), n: pairs.length };
}

function batchFeatures(b){
  const type = db.types.find(t=>t.id===b.typeId);
  const totalGreen = b.pieces.reduce((s,p)=>s+p.initialWeight,0);
  const totalCurrent = b.pieces.reduce((s,p)=>s+latestPieceWeight(p),0);
  const yieldReal = totalGreen>0 ? 100 * totalCurrent/totalGreen : null;
  const yieldTarget = b.targetYield || null;
  // Average salt % across Curado stages
  let saltPct = null;
  (b.stages||[]).forEach(s=>{
    if(s.brine && s.brine.saltPct){
      saltPct = (saltPct||0) + s.brine.saltPct;
    }
  });
  // Days total: start → finish
  let daysTotal = null;
  if(b.startedAt){
    const end = b.finishedAt ? new Date(b.finishedAt) : new Date();
    daysTotal = (end - new Date(b.startedAt))/(1000*60*60*24);
  }
  // Average thickness
  const avgThickness = b.pieces.reduce((s,p)=>s+(p.thickness||0),0)/Math.max(1,b.pieces.length);
  // Env from log (any stage)
  const env = envStats(b);
  // Compute aw of the heaviest/representative piece at current weight
  const repPiece = b.pieces[0];
  const safety = repPiece ? safetyStatus(b, repPiece) : null;
  // Receiving core T
  const coreT = b.receiving?.coreT ?? null;
  // Tasting
  const notaGlobal = b.tasting?.notaGlobal ?? null;
  const monthStarted = b.startedAt ? new Date(b.startedAt).getUTCMonth()+1 : null;
  const yearStarted = b.startedAt ? new Date(b.startedAt).getUTCFullYear() : null;
  return {
    batchId: b.id, ref: b.ref, typeId: b.typeId, typeName: b.typeName,
    status: b.status,
    yieldReal, yieldTarget,
    saltPct, daysTotal, avgThickness,
    avgT: env?.avgT ?? null, avgHR: env?.avgHR ?? null,
    aw: safety?.aw ?? null,
    coreT,
    notaGlobal,
    aroma: b.tasting?.aroma ?? null,
    textura: b.tasting?.textura ?? null,
    apariencia: b.tasting?.apariencia ?? null,
    monthStarted, yearStarted,
    startedAt: b.startedAt, finishedAt: b.finishedAt
  };
}

function historicalYieldStats(typeId){
  const batches = db.batches.filter(b => b.typeId===typeId && (b.status==='done' || b.status==='in_progress'));
  const yields = [];
  batches.forEach(b=>{
    const f = batchFeatures(b);
    if(f.yieldReal !== null && b.status==='done'){
      yields.push(f.yieldReal);
    }
  });
  if(yields.length === 0) return { n:0 };
  const mean = yields.reduce((s,v)=>s+v,0)/yields.length;
  const variance = yields.reduce((s,v)=>s+(v-mean)**2,0)/yields.length;
  const std = Math.sqrt(variance);
  const min = Math.min(...yields);
  const max = Math.max(...yields);
  return { n: yields.length, mean, std, min, max, yields };
}

function stageLossBreakdown(b){
  if(!b.stages || b.stages.length === 0) return [];
  const totalGreen = b.pieces.reduce((s,p)=>s+p.initialWeight,0);
  // Build timeline: for each stage, estimate the batch weight at the end
  // Use linear interpolation of weight logs across all pieces.
  const result = [];
  let prevWeight = totalGreen;
  b.stages.forEach((s)=>{
    const endDate = s.actualEnd || s.expectedEnd || null;
    if(!endDate) return;
    const endTs = new Date(endDate).getTime();
    // Sum weights across pieces at endTs (nearest log before+after, linear interp)
    let batchWeightAtEnd = 0;
    b.pieces.forEach(p=>{
      const logs = (p.weightLogs||[]).slice().sort((a,b)=>new Date(a.date)-new Date(b.date));
      const greenEntry = { date: b.startedAt, weight: p.initialWeight };
      const all = [greenEntry].concat(logs.map(l=>({date:l.date, weight:l.weight, outlier:l.outlier})))
                                .filter(l=>!l.outlier);
      // Find bracket
      let w = null;
      if(endTs <= new Date(all[0].date).getTime()) w = all[0].weight;
      else if(endTs >= new Date(all[all.length-1].date).getTime()) w = all[all.length-1].weight;
      else {
        for(let i=0; i<all.length-1; i++){
          const t1 = new Date(all[i].date).getTime();
          const t2 = new Date(all[i+1].date).getTime();
          if(endTs >= t1 && endTs <= t2){
            const f = (endTs - t1) / (t2 - t1);
            w = all[i].weight + f * (all[i+1].weight - all[i].weight);
            break;
          }
        }
      }
      batchWeightAtEnd += w ?? p.initialWeight;
    });
    const lossInStage = prevWeight - batchWeightAtEnd;
    const lossPct = totalGreen > 0 ? 100 * lossInStage / totalGreen : 0;
    result.push({
      kind: s.kind,
      startedAt: s.startedAt, endedAt: endDate,
      weightAtEnd: batchWeightAtEnd,
      lossInStage, lossPct
    });
    prevWeight = batchWeightAtEnd;
  });
  return result;
}

