const BACKUP_PREFIX = 'laforet_backup_';

const BACKUP_LAST_KEY = 'laforet_backup_last';

function autoBackup(){
  try{
    const today = toISODate(new Date());
    const last = localStorage.getItem(BACKUP_LAST_KEY);
    if(last === today) return; // already backed up today
    const key = BACKUP_PREFIX + today;
    localStorage.setItem(key, JSON.stringify({ ts: new Date().toISOString(), db }));
    localStorage.setItem(BACKUP_LAST_KEY, today);
    pruneBackups();
  }catch(e){ console.error('autoBackup failed', e); }
}

function pruneBackups(){
  const keys = [];
  for(let i=0; i<localStorage.length; i++){
    const k = localStorage.key(i);
    if(k && k.startsWith(BACKUP_PREFIX)) keys.push(k);
  }
  keys.sort(); // ISO dates sort chronologically
  if(keys.length <= 30) return;
  // Keep last 30, then 1 per month for older ones
  const keepLast30 = new Set(keys.slice(-30));
  const older = keys.slice(0, -30);
  const monthKept = {};
  const keepMonthly = new Set();
  for(const k of older){
    const date = k.slice(BACKUP_PREFIX.length);
    const month = date.slice(0, 7); // YYYY-MM
    if(!monthKept[month]){ monthKept[month] = k; keepMonthly.add(k); }
  }
  for(const k of keys){
    if(!keepLast30.has(k) && !keepMonthly.has(k)){
      localStorage.removeItem(k);
    }
  }
}

function listBackups(){
  const list = [];
  for(let i=0; i<localStorage.length; i++){
    const k = localStorage.key(i);
    if(k && k.startsWith(BACKUP_PREFIX)){
      try{
        const data = JSON.parse(localStorage.getItem(k));
        list.push({ key:k, date: k.slice(BACKUP_PREFIX.length), ts: data.ts, size: localStorage.getItem(k).length });
      }catch(e){}
    }
  }
  list.sort((a,b)=> b.date.localeCompare(a.date));
  return list;
}

function commitHistoricalImport(resolved){
  if(!resolved || !resolved.length){ return; }
  try{
    // Force a backup NOW regardless of day
    try{
      const key = BACKUP_PREFIX + toISODate(new Date()) + '-pre-import';
      localStorage.setItem(key, JSON.stringify({ ts: new Date().toISOString(), db }));
    }catch(e){ console.error('pre-import backup failed', e); }
    // Append batches
    let added = 0;
    resolved.forEach(b=>{
      // Ensure id uniqueness
      if(!b.id) b.id = uid('bat');
      if(db.batches.some(x=>x.id===b.id)) b.id = uid('bat');
      db.batches.push(b);
      added++;
    });
    saveDB();
    closeModal();
    render();
    toast(`✓ ${added} lotes históricos importados · backup pre-import guardado`);
  }catch(e){
    toast('Error al importar: '+e.message);
  }
}

function restoreBackup(key){
  if(!confirm('Restaurar este backup reemplazará TODOS los datos actuales. ¿Continuar?')) return;
  try{
    const data = JSON.parse(localStorage.getItem(key));
    if(!data || !data.db) throw new Error('backup inválido');
    db = data.db;
    saveDB();
    render();
    closeModal();
    toast('Backup restaurado · '+key.slice(BACKUP_PREFIX.length));
  }catch(e){
    toast('Error al restaurar: '+e.message);
  }
}

function uid(prefix='id'){ return prefix+'_'+Math.random().toString(36).slice(2,10); }

function fmt(n, d=1){ if(n===null||n===undefined||isNaN(n)) return '—'; return Number(n).toLocaleString('es-CO',{maximumFractionDigits:d, minimumFractionDigits: d>0 && n%1!==0 ? Math.min(d,2) : 0}); }

function fmtG(n){ if(n===null||n===undefined||isNaN(n)) return '—'; if(n>=1000) return (n/1000).toLocaleString('es-CO',{maximumFractionDigits:2})+' kg'; return Math.round(n).toLocaleString('es-CO')+' g'; }

function fmtGExact(n){ if(n===null||n===undefined||isNaN(n)) return '—'; return Math.round(n).toLocaleString('es-CO')+' g'; }

const APP_TZ = 'America/Bogota';

function fmtDate(d){ if(!d) return '—'; const D = new Date(d); return D.toLocaleDateString('es-CO',{day:'2-digit',month:'short',year:'2-digit',timeZone:APP_TZ}); }

function fmtDateShort(d){ if(!d) return '—'; const D = new Date(d); return D.toLocaleDateString('es-CO',{day:'2-digit',month:'2-digit',timeZone:APP_TZ}); }

function daysBetween(a,b){ return Math.floor((new Date(b) - new Date(a))/(1000*60*60*24)); }

function parseLocalDate(v){
  if(v instanceof Date) return v;
  if(typeof v !== 'string') return new Date(v);
  const m = v.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if(m){
    // Build ISO explicitly as midnight Bogota = YYYY-MM-DDT05:00:00Z (Bogota is UTC-5, no DST)
    return new Date(`${m[1]}-${m[2]}-${m[3]}T05:00:00.000Z`);
  }
  return new Date(v);
}

function addDays(d, days){
  // Use UTC math so we don't jump across DST or get wrong results in non-Bogota browsers.
  // Fractional days are rounded, since downstream formatters only show calendar day.
  const x = parseLocalDate(d);
  return new Date(x.getTime() + Math.round(days) * 86400000).toISOString();
}

function toISODate(d){
  const D = (d instanceof Date) ? d : parseLocalDate(d);
  // Use Intl in the Bogota tz to extract y/m/d consistently regardless of browser tz
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: APP_TZ, year:'numeric', month:'2-digit', day:'2-digit' }).formatToParts(D);
  const y = parts.find(p=>p.type==='year').value;
  const m = parts.find(p=>p.type==='month').value;
  const day = parts.find(p=>p.type==='day').value;
  return `${y}-${m}-${day}`;
}

function ebDays(thicknessCm, shape /*flat|tubular*/, plus20=false){
  if(!thicknessCm || thicknessCm<=0) return 0;
  const col = shape==='flat' ? (plus20?'flat20':'flat') : (plus20?'tub20':'tub');
  const t = Math.max(0.5, Math.min(20, thicknessCm));
  // find surrounding rows
  for(let i=0; i<EB_TABLE.length-1; i++){
    const a = EB_TABLE[i], b = EB_TABLE[i+1];
    if(t>=a.t && t<=b.t){
      const r = (t-a.t)/(b.t-a.t);
      return a[col] + r*(b[col]-a[col]);
    }
  }
  return EB_TABLE[EB_TABLE.length-1][col];
}

function nextRefFor(typeRef){
  // find highest existing sequence
  const used = db.batches.filter(b=>b.typeRef===typeRef).map(b=>parseInt((b.ref||'').replace(typeRef,'')||'0',10)).filter(x=>!isNaN(x));
  const n = used.length? Math.max(...used)+1 : 0;
  return typeRef + String(n).padStart(3,'0');
}

function nextSeqFor(typeRef){
  const used = db.batches.filter(b=>b.typeRef===typeRef).map(b=>parseInt((b.ref||'').replace(typeRef,'')||'0',10)).filter(x=>!isNaN(x));
  return used.length ? Math.max(...used)+1 : 0;
}

function refFromLot(typeRef, lot){
  if(!typeRef) return null;
  const digits = String(lot||'').replace(/\D/g,'');
  if(!digits) return null;
  return typeRef + digits.padStart(3,'0');
}

function previewRef(nb, type, excludeBatchId){
  if(!type) return '—';
  const fromLot = refFromLot(type.ref, nb.lot);
  if(fromLot){
    // Check collision with existing batches (excluding self in edit mode)
    const collision = db.batches.some(b => b.ref === fromLot && b.id !== excludeBatchId);
    return collision ? fromLot + ' ⚠ ya existe' : fromLot;
  }
  // No lot provided — use next available sequence
  return nextRefFor(type.ref);
}

