function typeTotalDays(type, thicknessCm=null, plus20=true){
  let total = 0;
  for(const s of type.stages){
    if(s.kind==='Curado' && s.eb && thicknessCm){
      total += ebDays(thicknessCm, s.shape||'tubular', plus20);
    } else {
      total += s.dEst || 0;
    }
  }
  return total;
}

let batchTab = 'piezas';

