function todaysAgenda(){
  const items = [];
  const now = Date.now();
  const activeBatches = db.batches.filter(b=>b.status==='in_progress');
  activeBatches.forEach(b=>{
    const sec = findSecadoStage(b);
    // A stage is "truly active" only if it has started AND today is at/past that start AND it's not done
    const secActive = sec && sec.startedAt && new Date(sec.startedAt).getTime() <= now && !sec.done;
    // Pesajes vencidos (>7d sin registro durante Secado) — solo cuando Secado realmente arrancó
    if(secActive){
      b.pieces.forEach(p=>{
        const logs = (p.weightLogs||[]).slice().sort((a,b)=>new Date(b.date)-new Date(a.date));
        const latest = logs[0];
        const secStartMs = new Date(sec.startedAt).getTime();
        // Base de referencia: último log o el inicio de Secado (lo que sea más reciente)
        const refMs = latest ? Math.max(new Date(latest.date).getTime(), secStartMs) : secStartMs;
        const daysSince = Math.floor((now - refMs)/(1000*60*60*24));
        const safety = safetyStatus(b, p);
        if(safety.ready) return;
        if(daysSince >= 7){
          items.push({ kind:'weigh', urgency: daysSince, batchId:b.id, pieceId:p.id,
                       label: `Pesar ${p.code} (${b.ref})`, note: latest ? `${daysSince}d sin registro` : `${daysSince}d desde inicio Secado · sin registros aún` });
        }
      });
    }
    // Piezas en objetivo listas (aw cumplido pero stage sin cerrar) — también requiere Secado activo
    if(secActive){
      b.pieces.forEach(p=>{
        const safety = safetyStatus(b, p);
        if(safety.aw!==null && safety.aw <= safety.awTarget){
          items.push({ kind:'ready', urgency: 100, batchId:b.id, pieceId:p.id,
                       label: `${p.code} en objetivo (${b.ref})`, note: `aw ${safety.aw.toFixed(3)} ≤ ${safety.awTarget.toFixed(2)} · considerá avanzar etapa` });
        }
      });
    }
    // PCCs: receiving sin core T registrada
    if(!b.receiving || b.receiving.coreT===null || b.receiving.coreT===undefined){
      items.push({ kind:'pcc', urgency: 90, batchId:b.id,
                   label: `${b.ref} sin core T de recepción`, note: 'PCC HACCP #22 pendiente' });
    } else if(b.receiving.coreT > 4 && b.receiving.acceptance==='pending'){
      items.push({ kind:'pcc', urgency: 95, batchId:b.id,
                   label: `${b.ref} recepción con T>4°C sin decisión`, note: 'Documentar aceptar/rechazar' });
    }
    // Fermentación: pH no registrado en 24h — solo si Fermentado realmente arrancó
    const fermStage = (b.stages||[]).find(s=>s.kind==='Fermentado' && !s.done && s.startedAt && new Date(s.startedAt).getTime() <= now);
    if(fermStage){
      const hoursInFerm = (now - new Date(fermStage.startedAt).getTime())/(1000*60*60);
      const phLogs = (b.phLogs||[]).filter(l=>l.stageKind==='Fermentado');
      const latestPh = phLogs.sort((a,b)=>new Date(b.date)-new Date(a.date))[0];
      if(hoursInFerm > 24 && (!latestPh || latestPh.ph > 5.3)){
        items.push({ kind:'ferm', urgency: 110, batchId:b.id,
                     label: `⚠ Fermentación ${b.ref}: pH ${latestPh?latestPh.ph:'no registrado'}`, note: hoursInFerm.toFixed(0)+'h en fermentación · pH debe caer <5.3' });
      }
    }
    // Etapas vencidas
    const cs = currentStage(b);
    if(cs && cs.expectedEnd){
      const eta = daysBetween(new Date(), cs.expectedEnd);
      if(eta < 0){
        items.push({ kind:'stage', urgency: 80 + Math.min(20, -eta), batchId:b.id,
                     label: `${cs.kind} de ${b.ref} vencida`, note: `${-eta}d vencida · revisar/avanzar` });
      }
    }
    // v2.1 #18 — Danger Zone contextual por etapa (usa envLog Govee).
    // Solo evaluar si la etapa actual realmente arrancó (startedAt <= now).
    const csActive = cs && cs.startedAt && new Date(cs.startedAt).getTime() <= now;
    const envStage = csActive ? envStats(b, cs.kind) : null;
    if(envStage && envStage.avgT !== null){
      const avgT = envStage.avgT;
      if(cs.kind === 'Curado' && avgT > 6){
        items.push({ kind:'danger', urgency: 115, batchId:b.id,
                     label: `⚠ ${b.ref}: Curado a ${avgT.toFixed(1)}°C`, note: `Promedio sobre 6°C — sal aún difundiendo con aw alta` });
      } else if((cs.kind === 'Secado' || cs.kind === 'Madurado')){
        // Alert if avg T > target+5 AND at least one piece still vulnerable (aw > AW_NO_BARRIER)
        const target = 13;
        const vulnerable = b.pieces.some(p=>{
          const s = safetyStatus(b, p);
          return s.aw !== null && s.aw > AW_NO_BARRIER;
        });
        if(avgT > target + 5 && vulnerable){
          items.push({ kind:'danger', urgency: 112, batchId:b.id,
                       label: `⚠ ${b.ref}: ${cs.kind} a ${avgT.toFixed(1)}°C con pieza vulnerable`, note: `Deriva >5°C sobre target 13°C y hay pieza con aw>${AW_NO_BARRIER.toFixed(2)}` });
        }
      }
    }
    // Recepción con core T > 4°C alerta más fuerte
    if(b.receiving && b.receiving.coreT !== null && b.receiving.coreT > 4){
      items.push({ kind:'danger', urgency: 108, batchId:b.id,
                   label: `${b.ref}: recibido a ${(+b.receiving.coreT).toFixed(1)}°C`, note: 'Core T sobre umbral HACCP — procesar hoy o descartar' });
    }
    // v2.2 #16 — HACCP critical PCC failures
    if(typeof evaluateHaccp === 'function'){
      const hac = evaluateHaccp(b);
      hac.results.filter(r=>r.status==='fail').forEach(r=>{
        const sev = r.pcc.severity==='critical' ? 120 : 95;
        items.push({ kind:'pcc-fail', urgency: sev, batchId:b.id,
                     label: `${b.ref}: ${r.pcc.label}`, note: `PCC violado · ${r.detail}` });
      });
    }
    // Case hardening: alerta si Secado realmente arrancó con VPD alto
    const secCh = findSecadoStage(b);
    const secChActive = secCh && secCh.startedAt && new Date(secCh.startedAt).getTime() <= now && !secCh.done;
    if(secChActive){
      const thickest = b.pieces.reduce((a,b)=> (a.thickness||0)>(b.thickness||0)?a:b, b.pieces[0]);
      if(thickest){
        const r = caseHardeningRisk(b, thickest);
        if(r && r.risk){
          items.push({ kind:'ch', urgency: 85, batchId:b.id,
                       label: `${b.ref}: posible case hardening`, note: r.msg });
        }
      }
    }
  });
  // v3.7 — Catas: lotes terminados por debajo de la meta del tipo, o sin cata registrada
  db.batches.forEach(b=>{
    if(b.status!=='done') return;
    const type = db.types.find(t=>t.id===b.typeId);
    const sc = batchScore(b);
    if(sc!=null && type?.tasteTarget && sc < type.tasteTarget){
      items.push({ kind:'tasting', urgency: 50, batchId:b.id,
                   label: `${b.ref}: cata ${sc} por debajo de la meta ${type.tasteTarget}`, note: 'Revisá defectos y la «receta ganadora» en Analytics antes del próximo lote' });
    } else if(tastingList(b).length===0 && b.finishedAt && (Date.now()-new Date(b.finishedAt).getTime()) < 45*86400000){
      items.push({ kind:'tasting', urgency: 30, batchId:b.id,
                   label: `${b.ref}: sin cata registrada`, note: 'Una cata alimenta calibración, defectos y punto óptimo' });
    }
  });
  // Sort by urgency desc
  items.sort((a,b)=> b.urgency - a.urgency);
  return items;
}

function currentStage(b){
  if(!b || !b.stages) return null;
  return b.stages.find(s=>!s.done) || null;
}

function latestWeight(b){
  // sum of latest weight of each piece; undefined if no piece has any log
  const anyLog = b.pieces.some(p=>(p.weightLogs||[]).length>0);
  if(!anyLog) return undefined;
  return b.pieces.reduce((s,p)=> s + latestPieceWeight(p), 0);
}

function batchProgressPct(b){
  const total = b.stages.length;
  const doneCount = b.stages.filter(s=>s.done).length;
  const cs = currentStage(b);
  let extra = 0;
  if(cs){
    const start = new Date(cs.startedAt || b.startedAt);
    const end = new Date(cs.expectedEnd || cs.startedAt);
    const now = new Date();
    if(end>start) extra = Math.min(1, Math.max(0, (now-start)/(end-start)));
  }
  return Math.min(100, 100*(doneCount+extra)/total);
}

function timeStatusForStage(s){
  if(s.done) return { level:'gray', label:'Terminada', pct:100 };
  if(!s.startedAt || !s.expectedEnd) return { level:'gray', label:'Sin fechas', pct:0 };
  const start = new Date(s.startedAt).getTime();
  const end = new Date(s.expectedEnd).getTime();
  const now = Date.now();
  const total = end - start;
  const elapsed = now - start;
  const pct = total>0? (elapsed/total)*100 : 0;
  if(pct >= 100) return { level:'green', label:'Lista · pasar a siguiente', pct };
  if(pct >= 80) return { level:'yellow', label:'Casi lista', pct };
  return { level:'red', label:'En proceso', pct };
}

function latestPieceWeight(piece, b){
  const logs = (piece.weightLogs||[]).slice().sort((a,b)=>new Date(b.date)-new Date(a.date));
  if(logs[0]) return logs[0].weight;
  if(b){
    const startW = pieceStartWeight(b, piece);
    if(startW) return startW;
  }
  return piece.initialWeight;
}

function findSecadoStage(b){
  if(!b || !b.stages) return null;
  // Prefer the first in-progress Secado stage
  let s = b.stages.find(st=>st.kind==='Secado' && st.startedAt && !st.done);
  if(s) return s;
  // Fallback: first Secado stage (may be done or not yet started)
  return b.stages.find(st=>st.kind==='Secado') || null;
}

function batchLossTargetPct(b){
  const s = findSecadoStage(b);
  if(s && typeof s.lossTargetPct === 'number' && s.lossTargetPct > 0) return s.lossTargetPct;
  return 100 - (b.targetYield || 60);
}

function pieceStartWeight(b, piece){
  const s = findSecadoStage(b);
  // Priority 1: explicit registration via Iniciar Secado modal
  if(s && s.startWeights){
    const w = s.startWeights[piece.id];
    if(w && w > 0) return w;
  }
  // Priority 2: earliest weight log for this piece (chronological first)
  const logs = (piece.weightLogs||[]).slice().sort((a,b)=>new Date(a.date)-new Date(b.date));
  if(logs.length > 0 && logs[0].weight > 0) return logs[0].weight;
  return null;
}

function pieceStartWeightExplicit(b, piece){
  const s = findSecadoStage(b);
  if(!s || !s.startWeights) return false;
  const w = s.startWeights[piece.id];
  return !!(w && w > 0);
}

function pieceTargetWeight(b, piece){
  const lossPct = batchLossTargetPct(b);
  const startW = pieceStartWeight(b, piece);
  if(startW) return startW * (1 - lossPct/100);
  // Last-resort fallback: green weight (BEFORE any curing loss)
  return (1 - lossPct/100) * piece.initialWeight;
}

function needsSecadoStartWeights(b){
  const s = findSecadoStage(b);
  if(!s || !s.startedAt) return false;
  return b.pieces.some(p => !pieceStartWeight(b, p));
}

function fitExpDecay(samples, Wtarget){
  if(!samples || samples.length < 2 || !Wtarget) return { hasEnough:false };
  const W0 = samples[0].w;
  if(W0 <= Wtarget) return { hasEnough:true, k:0, daysRemaining:0, pctComplete:100 };
  // Transform: let y = (W - Wtarget) / (W0 - Wtarget). Then y = exp(-k*t)
  // => ln(y) = -k * t. Linear regression through origin, t vs -ln(y).
  const points = samples.map(s=>{
    const y = (s.w - Wtarget) / (W0 - Wtarget);
    return { t: s.t, lny: y > 0 ? Math.log(y) : null };
  }).filter(p=>p.lny !== null && isFinite(p.lny) && p.t > 0);
  if(points.length < 1) return { hasEnough:false };
  // #11 v2.1 — WEIGHTED least squares with recency bias.
  // Weight: the latest 3 samples get 2× weight; critical because at 70-90%
  // progress the drying asymptotes and early samples would otherwise dominate k.
  const N = points.length;
  const weighted = points.map((p, i)=>{
    const isRecent = i >= Math.max(0, N - 3);
    return { ...p, w: isRecent ? 2 : 1 };
  });
  let num = 0, den = 0;
  for(const p of weighted){ num += p.w * p.t * p.lny; den += p.w * p.t * p.t; }
  if(den === 0) return { hasEnough:false };
  const k = -num / den;
  if(k <= 0) return { hasEnough:false, k, note:'La pieza no esta perdiendo peso' };
  // Current state: latest sample
  const last = samples[samples.length-1];
  const Wnow = last.w;
  // Days from NOW to reach target: solve W(t_total) = Wtarget with threshold W_target * 1.01
  // t_total = -ln((W_threshold - Wtarget)/(W0 - Wtarget)) / k
  const Wthreshold = Wtarget * 1.01;  // 1% tolerance
  const yThreshold = (Wthreshold - Wtarget) / (W0 - Wtarget);
  if(yThreshold <= 0) return { hasEnough:true, k, daysRemaining:0, pctComplete:100 };
  const tTotal = -Math.log(yThreshold) / k;
  const daysRemaining = Math.max(0, tTotal - last.t);
  // % complete based on weight-loss progress
  const totalLoss = W0 - Wtarget;
  const doneLoss = W0 - Wnow;
  const pctComplete = totalLoss > 0 ? Math.min(100, (doneLoss/totalLoss)*100) : 0;
  return { hasEnough:true, k, daysRemaining, pctComplete, tTotal, Wnow };
}

function pieceSecadoSamples(b, piece){
  const s = findSecadoStage(b);
  if(!s || !s.startedAt || !s.startWeights) return [];
  const startW = s.startWeights[piece.id];
  if(!startW) return [];
  const startTime = new Date(s.startedAt).getTime();
  const samples = [{ t: 0, w: startW, date: s.startedAt }];
  (piece.weightLogs||[]).forEach(l=>{
    if(l.outlier) return; // #12: exclude flagged outliers from the fit
    const t = (new Date(l.date).getTime() - startTime) / (1000*60*60*24);
    if(t > 0) samples.push({ t, w: l.weight, date: l.date });
  });
  samples.sort((a,b)=>a.t - b.t);
  return samples;
}

function pieceEstimation(b, piece){
  const s = findSecadoStage(b);
  if(!s || !s.startedAt) return null;
  const target = pieceTargetWeight(b, piece);
  const samples = pieceSecadoSamples(b, piece);
  if(samples.length < 2){
    return { target, samples, hasEnough:false, note: samples.length<1 ? 'Falta registro inicial de Secado' : 'Falta al menos una medicion mas' };
  }
  const fit = fitExpDecay(samples, target);
  if(!fit.hasEnough) return { target, samples, hasEnough:false, note: fit.note || 'Datos insuficientes' };
  const now = new Date();
  const estCompletion = new Date(now.getTime() + fit.daysRemaining * 24*60*60*1000);
  return { target, samples, hasEnough:true, ...fit, estCompletion };
}

function weightStatusForPiece(b, piece){
  const target = pieceTargetWeight(b, piece);
  const current = latestPieceWeight(piece, b);
  const startW = pieceStartWeight(b, piece) || piece.initialWeight;
  const totalLoss = startW - target;
  const doneLoss = startW - current;
  const pct = totalLoss>0? (doneLoss/totalLoss)*100 : 0;
  const deltaPct = target>0 ? ((current-target)/target)*100 : 0;
  // hasLog: true if we have ANY basis for the start weight — either an
  // explicit "Iniciar Secado" registration (s.startWeights) or a weekly
  // weightLog. Previously this only checked weightLogs, so registering
  // the Secado start weight alone never cleared the "needsStart" alert.
  const hasStartW = !!pieceStartWeight(b, piece);
  const hasLog = (piece.weightLogs||[]).length > 0 || hasStartW;
  if(!hasLog) return { level:'gray', label:'Sin registro', current, target, pct:0, deltaPct, hasLog, needsStart:true };
  if(current <= target*1.02) return { level:'green', label:'Peso objetivo alcanzado', current, target, pct, deltaPct, hasLog };
  if(current <= target*1.05) return { level:'yellow', label:'Cerca del objetivo', current, target, pct, deltaPct, hasLog };
  return { level:'red', label:'Aún secando', current, target, pct, deltaPct, hasLog };
}

function weightStatusForBatch(b){
  // Sum of per-piece targets uses the new piece-based target (stage start * (1-loss))
  const target = b.pieces.reduce((s,p)=>s + pieceTargetWeight(b,p), 0);
  const startW = b.pieces.reduce((s,p)=> s + (pieceStartWeight(b,p) || p.initialWeight), 0);
  const current = b.pieces.reduce((s,p)=>s+latestPieceWeight(p),0);
  const totalLoss = startW - target;
  const doneLoss = startW - current;
  const pct = totalLoss>0? (doneLoss/totalLoss)*100 : 0;
  const deltaPct = target>0 ? ((current-target)/target)*100 : 0;
  const levels = b.pieces.map(p=>weightStatusForPiece(b,p).level);
  const order = {red:3, yellow:2, green:1, gray:0};
  const worst = levels.reduce((w,l)=> order[l]>order[w]?l:w, 'gray');
  const labels = {red:'Aún secando', yellow:'Cerca del objetivo', green:'Peso objetivo alcanzado', gray:'Pendiente iniciar o sin registros'};
  return { level:worst, label:labels[worst], current, target, pct, deltaPct };
}

function latestBatchMeasurementDate(b){
  let latest = null;
  b.pieces.forEach(p=> (p.weightLogs||[]).forEach(l=>{
    const t = new Date(l.date).getTime();
    if(latest===null || t>latest) latest = t;
  }));
  return latest;
}

function migrateBackfillBrineOnBatches(){
  // For batches created before build14, the Curado stage may be missing brine.
  // Try to backfill from the parent type. If not available, use a sensible default.
  let touched = false;
  (db.batches||[]).forEach(b=>{
    const parentType = (db.types||[]).find(t=>t.id===b.typeId);
    (b.stages||[]).forEach((s, si)=>{
      if(s.kind==='Curado' && !s.brine){
        let src = null;
        if(parentType && parentType.stages){
          // Find the corresponding Curado stage in the type (same index or first Curado)
          src = parentType.stages[si] && parentType.stages[si].kind==='Curado'
            ? parentType.stages[si]
            : parentType.stages.find(x=>x.kind==='Curado');
        }
        if(src && src.brine){
          s.brine = {
            saltPct: src.brine.saltPct,
            waterPct: src.brine.waterPct,
            saltIngredient: src.brine.saltIngredient,
            cureSalt: src.brine.cureSalt ? { ...src.brine.cureSalt } : { ingredient:null, gPerKg:0 }
          };
        } else {
          s.brine = { saltPct:2.8, waterPct:0, saltIngredient: defaultCommonSaltName(), cureSalt:{ ingredient:null, gPerKg:0 } };
        }
        // Also backfill shape/eb if missing
        if(s.shape===undefined && src) s.shape = src.shape || 'tubular';
        if(s.eb===undefined && src) s.eb = src.eb || false;
        touched = true;
      }
    });
  });
  if(touched){ console.log('Brine backfilled on existing batches'); saveDB(); }
}

function migrateStripSaltFromCureBatches(){
  let touched = false;
  (db.batches||[]).forEach(b=>{
    (b.stages||[]).forEach(s=>{
      if(s.kind==='Curado' && Array.isArray(s.recipe)){
        const before = s.recipe.length;
        s.recipe = s.recipe.filter(r=>{
          const ing = db.ingredients.find(x=>x.name===r.ingredient);
          return !ing || (ing.category!=='sal' && ing.category!=='sal-curado');
        });
        if(s.recipe.length !== before) touched = true;
      }
    });
  });
  if(touched){ console.log('Sales removidas de recetas de curado en lotes activos'); saveDB(); }
}

function migrateWeightLogsToPieces(){
  let migrated = 0;
  (db.batches||[]).forEach(b=>{
    // ensure every piece has code + weightLogs
    (b.pieces||[]).forEach((p,i)=>{
      if(!p.weightLogs) p.weightLogs = [];
      if(!p.code) p.code = (b.ref||'LOTE') + String.fromCharCode(65+i);
    });
    // if legacy batch-level weightLogs exist, move them to piece #0 as approximation
    if(Array.isArray(b.weightLogs) && b.weightLogs.length>0 && b.pieces && b.pieces.length>0){
      const totalW = b.pieces.reduce((s,p)=>s+p.initialWeight,0);
      const p0 = b.pieces[0];
      b.weightLogs.forEach(l=>{
        // scale legacy total-batch weight down to piece 0's proportion
        const scaled = l.weight * (p0.initialWeight/totalW);
        p0.weightLogs.push({
          id: uid('wl'),
          date: l.date,
          weight: Math.round(scaled),
          note: (l.note||'') + ' [migrado del lote]'
        });
      });
      migrated++;
      delete b.weightLogs;
    }
  });
  if(migrated>0){ console.log('Migrados', migrated, 'lotes a peso-por-pieza'); saveDB(); }
}

function phLevel(val, ph){
  if(val===undefined||val===null||val==='') return null;
  const v = +val;
  if(v<ph.dangerLow || v>ph.dangerHigh) return 'alert';   // out of safe range → orange skull
  if(v<ph.start-0.3 || v>ph.start+0.3) return 'yellow';   // outside expected window → yellow
  return 'green';                                          // within window → green
}

function stepSmoke(typeId, idx, field, delta){
  const t = db.types.find(x=>x.id===typeId);
  const s = t.stages[idx];
  if(!s.smoke) s.smoke = { hours:6, tempC:22, woods:['Nogal'] };
  const bounds = { hours:[0,72], tempC:[10,150] };
  const [min,max] = bounds[field] || [0, 999];
  const cur = +s.smoke[field] || 0;
  const next = Math.max(min, Math.min(max, cur + delta));
  s.smoke[field] = next;
  saveDB(); render();
}

function toggleWood(typeId, idx, woodName){
  const t = db.types.find(x=>x.id===typeId);
  const s = t.stages[idx];
  if(!s.smoke) s.smoke = { hours:6, tempC:22, woods:[] };
  if(!s.smoke.woods) s.smoke.woods = [];
  const i = s.smoke.woods.indexOf(woodName);
  if(i>=0) s.smoke.woods.splice(i,1);
  else s.smoke.woods.push(woodName);
  saveDB(); render();
}

function stepBrine(typeId, idx, field, delta){
  const t = db.types.find(x=>x.id===typeId);
  const st = t.stages[idx];
  if(!st.brine) st.brine = { saltPct:2.8, waterPct:0, saltIngredient: defaultCommonSaltName(), cureSalt:{ingredient:null, gPerKg:0} };
  const bounds = { saltPct:[0.5,6], waterPct:[0,50] };
  const [min,max] = bounds[field] || [0, 999];
  const cur = +st.brine[field] || 0;
  const next = Math.max(min, Math.min(max, +(cur + delta).toFixed(2)));
  st.brine[field] = next;
  saveDB(); render();
}

function stepCureSalt(typeId, idx, delta){
  const t = db.types.find(x=>x.id===typeId);
  const st = t.stages[idx];
  if(!st.brine) st.brine = { saltPct:2.8, waterPct:0, saltIngredient: defaultCommonSaltName(), cureSalt:{ingredient:null, gPerKg:0} };
  if(!st.brine.cureSalt) st.brine.cureSalt = { ingredient:null, gPerKg:0 };
  if(!st.brine.cureSalt.ingredient) return;
  const cureIng = cureSaltByName(st.brine.cureSalt.ingredient);
  const max = cureIng?.maxGPerKg || 4;
  const cur = +st.brine.cureSalt.gPerKg || 0;
  const next = Math.max(0, Math.min(max, +(cur + delta).toFixed(2)));
  st.brine.cureSalt.gPerKg = next;
  saveDB(); render();
}

function updateCureSalt(typeId, idx, field, value){
  const t = db.types.find(x=>x.id===typeId);
  const st = t.stages[idx];
  if(!st.brine) st.brine = {saltPct:2.8, waterPct:0, saltIngredient: defaultCommonSaltName(), cureSalt:{ingredient:null, gPerKg:0}};
  if(!st.brine.cureSalt) st.brine.cureSalt = {ingredient:null, gPerKg:0};
  if(field==='ingredient' && !value){
    st.brine.cureSalt.ingredient = null;
    st.brine.cureSalt.gPerKg = 0;
  } else {
    st.brine.cureSalt[field] = value;
    if(field==='ingredient' && (!st.brine.cureSalt.gPerKg || st.brine.cureSalt.gPerKg===0)){
      st.brine.cureSalt.gPerKg = 2.5;
    }
  }
  saveDB(); renderIfNoFocus();
}

function updateBrine(typeId, idx, field, value){
  const t = db.types.find(x=>x.id===typeId);
  if(!t.stages[idx].brine) t.stages[idx].brine = {saltPct:2.8, waterPct:0, saltIngredient: defaultSaltName(), cureSalt:{ingredient:null, gPerKg:0}};
  t.stages[idx].brine[field] = value;
  saveDB(); renderIfNoFocus();
}

function ingredientUsage(name){
  const u = { recipe:0, brine:0, cure:0, inoc:0, meat:0, types:0, batches:0, total:0 };
  const stageHits = (stages) => {
    let hit = false;
    (stages||[]).forEach(s=>{
      if(s.recipe?.some(r=>r.ingredient===name)){ u.recipe++; hit = true; }
      if(s.brine?.saltIngredient===name){ u.brine++; hit = true; }
      if(s.brine?.cureSalt?.ingredient===name){ u.cure++; hit = true; }
      if(s.inoc?.i===name){ u.inoc++; hit = true; }
    });
    return hit;
  };
  (db.types||[]).forEach(t=>{
    let hit = stageHits(t.stages);
    if(t.baseMeat?.composition?.some(c=>c.ingredient===name)){ u.meat++; hit = true; }
    if(hit) u.types++;
  });
  (db.batches||[]).forEach(b=>{
    let hit = stageHits(b.stages);
    // Los lotes no guardan su propia composición de carne: la heredan del tipo
    // (type.baseMeat) a través de b.typeId. b.baseMeat nunca se asigna en el código.
    const parentType = (db.types||[]).find(t=>t.id===b.typeId);
    if(parentType?.baseMeat?.composition?.some(c=>c.ingredient===name)){ u.meat++; hit = true; }
    if(hit) u.batches++;
  });
  u.total = u.types + u.batches;
  return u;
}

function ingredientUsageDetail(u){
  const parts = [];
  if(u.recipe) parts.push(`${u.recipe} receta${u.recipe===1?'':'s'} de etapa`);
  if(u.brine)  parts.push(`${u.brine} salmuera${u.brine===1?'':'s'}`);
  if(u.cure)   parts.push(`${u.cure} sal${u.cure===1?'':'es'} de curado`);
  if(u.inoc)   parts.push(`${u.inoc} inoculación${u.inoc===1?'':'es'}`);
  if(u.meat)   parts.push(`${u.meat} composición${u.meat===1?'':'es'} de carne`);
  return parts.join(', ');
}

function meatMetaTag(ing){
  const m = ing.meat;
  if(!m) return '';
  const animal = m.animal ? m.animal.charAt(0).toUpperCase()+m.animal.slice(1) : '';
  if(m.kind === 'corte') return `${animal} · corte: ${m.cut||'—'}`;
  const fat = {magro:'magro', entreverado:'entreverado', grasa:'grasa pura'}[m.fatLevel] || '';
  return `${animal} · genérica${fat?' · '+fat:''}`;
}

function completeStage(batchId, idx){
  const b = db.batches.find(x=>x.id===batchId);
  const s = b.stages[idx];
  s.done = true;
  s.actualEnd = new Date().toISOString();
  // shift downstream stages to start now
  const now = new Date();
  let cursor = now;
  for(let i=idx+1;i<b.stages.length;i++){
    const ns = b.stages[i];
    ns.startedAt = new Date(cursor).toISOString();
    ns.expectedEnd = addDays(cursor, ns.dEst);
    cursor = new Date(ns.expectedEnd);
  }
  // if all done, mark batch done
  if(b.stages.every(s=>s.done)){ b.status='done'; b.finishedAt=new Date().toISOString(); }
  saveDB(); render(); toast('Etapa completada');
}

