function piecesNeedingWeighing(){
  const list = [];
  const now = Date.now();
  db.batches.filter(b=>b.status==='in_progress').forEach(b=>{
    const sec = findSecadoStage(b);
    if(!sec || !sec.startedAt) return;
    if(new Date(sec.startedAt).getTime() > now) return; // Secado hasn't started yet
    if(sec.done) return;
    b.pieces.forEach(p=>{
      const logs = (p.weightLogs||[]).slice().sort((a,b)=>new Date(b.date)-new Date(a.date));
      const latest = logs[0];
      const daysSince = latest ? Math.floor((Date.now() - new Date(latest.date).getTime())/(1000*60*60*24)) : 999;
      const safety = safetyStatus(b, p);
      if(safety.ready) return; // already finished → no need to weigh
      list.push({ batchId: b.id, pieceId: p.id, code: p.code, batchRef: b.ref, typeName: b.typeName,
                  latest: latest?latest.weight:p.initialWeight,
                  target: pieceTargetWeight(b, p),
                  daysSince, aw: safety.aw });
    });
  });
  list.sort((a,b)=> b.daysSince - a.daysSince);
  return list;
}

