const SCORE_WEIGHTS = { sabor:35, aroma:20, textura:20, apariencia:15, equilibrio:10 };

const DEFECT_PENALTY = [0, 0.3, 0.8, 2];

function suggestTastingScore(r){
  const has = v => v!==null && v!==undefined && v!=='' && !isNaN(+v);
  const q10 = v => (+v-1)*2.5;
  const parts = [];
  const sq = FLAVOR_AXES.map(f=>r[f.k+'Q']).filter(has).map(q10);
  if(sq.length) parts.push({w:SCORE_WEIGHTS.sabor, v:sq.reduce((a,b)=>a+b,0)/sq.length});
  if(has(r.aroma)) parts.push({w:SCORE_WEIGHTS.aroma, v:q10(r.aroma)});
  if(has(r.textura)) parts.push({w:SCORE_WEIGHTS.textura, v:q10(r.textura)});
  if(has(r.apariencia)) parts.push({w:SCORE_WEIGHTS.apariencia, v:q10(r.apariencia)});
  const ints = [r.aromaInt, ...FLAVOR_AXES.map(f=>r[f.k])].filter(has);
  if(ints.length) parts.push({w:SCORE_WEIGHTS.equilibrio, v:ints.reduce((a,x)=>a+(1-Math.abs(+x-3)/2)*10,0)/ints.length});
  if(!parts.length) return null;
  const W = parts.reduce((a,p)=>a+p.w,0);
  let n = parts.reduce((a,p)=>a+p.w*p.v,0)/W;
  n -= (r.defectos||[]).reduce((a,d)=>a+(DEFECT_PENALTY[d.sev]||0),0);
  n = Math.max(0, Math.min(10, n));
  return Math.round(n*2)/2;
}

function defState(t, name){
  const d = (t.defectos||[]).find(x=>x.name===name);
  if(d && d.sev>0) return String(d.sev);
  if((t.defOk||[]).includes(name)) return '0';
  return '';
}

