const IDB_NAME = 'laforet_sync';

const IDB_STORE = 'handles';

let _cloudHandle = null;

let _cloudSaveTimer = null;

let _cloudStatus = 'off';

function idbGet(key){
  return new Promise((resolve,reject)=>{
    const req = indexedDB.open(IDB_NAME, 1);
    req.onupgradeneeded = ()=>{ req.result.createObjectStore(IDB_STORE); };
    req.onsuccess = ()=>{
      const tx = req.result.transaction(IDB_STORE, 'readonly');
      const store = tx.objectStore(IDB_STORE);
      const g = store.get(key);
      g.onsuccess = ()=> resolve(g.result);
      g.onerror = ()=> reject(g.error);
    };
    req.onerror = ()=> reject(req.error);
  });
}

function idbSet(key, val){
  return new Promise((resolve,reject)=>{
    const req = indexedDB.open(IDB_NAME, 1);
    req.onupgradeneeded = ()=>{ req.result.createObjectStore(IDB_STORE); };
    req.onsuccess = ()=>{
      const tx = req.result.transaction(IDB_STORE, 'readwrite');
      const store = tx.objectStore(IDB_STORE);
      const p = store.put(val, key);
      p.onsuccess = ()=> resolve();
      p.onerror = ()=> reject(p.error);
    };
    req.onerror = ()=> reject(req.error);
  });
}

function idbDel(key){
  return new Promise((resolve,reject)=>{
    const req = indexedDB.open(IDB_NAME, 1);
    req.onupgradeneeded = ()=>{ req.result.createObjectStore(IDB_STORE); };
    req.onsuccess = ()=>{
      const tx = req.result.transaction(IDB_STORE, 'readwrite');
      const store = tx.objectStore(IDB_STORE);
      const d = store.delete(key);
      d.onsuccess = ()=> resolve();
      d.onerror = ()=> reject(d.error);
    };
    req.onerror = ()=> reject(req.error);
  });
}

async function icloudUnlink(){
  if(!confirm('¿Desvincular el archivo iCloud? Los datos locales quedan intactos.')) return;
  _cloudHandle = null;
  _cloudStatus = 'off';
  await idbDel('cloudHandle');
  toast('Desvinculado');
  renderIcloudStatus();
  renderSyncModalBody();
}

async function icloudEnsurePermission(mode){
  if(!_cloudHandle) return false;
  const opts = { mode };
  if((await _cloudHandle.queryPermission(opts)) === 'granted') return true;
  if((await _cloudHandle.requestPermission(opts)) === 'granted') return true;
  _cloudStatus = 'denied';
  renderIcloudStatus();
  return false;
}

async function icloudPush(manual){
  if(!_cloudHandle){ if(manual) toast('No hay archivo vinculado'); return; }
  try {
    if(!(await icloudEnsurePermission('readwrite'))){ if(manual) toast('Permiso denegado'); return; }
    const w = await _cloudHandle.createWritable();
    await w.write(JSON.stringify(db, null, 2));
    await w.close();
    _cloudStatus = 'linked';
    renderIcloudStatus();
    if(manual) toast('Guardado en iCloud');
  } catch(err){
    console.error('iCloud push error', err);
    _cloudStatus = 'error';
    renderIcloudStatus();
    if(manual) toast('Error al guardar');
  }
}

function icloudDebouncedPush(){
  if(!_cloudHandle) return;
  clearTimeout(_cloudSaveTimer);
  _cloudSaveTimer = setTimeout(()=>{ icloudPush(); }, 800);
}

async function icloudRestoreHandle(){
  try {
    const h = await idbGet('cloudHandle');
    if(h){
      _cloudHandle = h;
      // don't request permission on boot — wait for first write
      _cloudStatus = 'linked';
      renderIcloudStatus();
    }
  } catch(err){ /* first run */ }
}

async function ensureHandlePermission(handle, mode){
  const opts = { mode };
  if((await handle.queryPermission(opts)) === 'granted') return true;
  if((await handle.requestPermission(opts)) === 'granted') return true;
  return false;
}

let dragIdx = null;

function dragStart(e, idx){ dragIdx = idx; e.target.classList.add('dragging'); e.dataTransfer.effectAllowed='move'; }

function dragOver(e){ e.preventDefault(); e.currentTarget.classList.add('dragover'); }

function dropStage(e, idx){
  e.preventDefault();
  if(dragIdx===null || dragIdx===idx) return;
  const t = editingType;
  const [s] = t.stages.splice(dragIdx,1);
  t.stages.splice(idx,0,s);
  dragIdx = null; saveDB(); render();
}

function escapeHtml(s){ return String(s??'').replace(/[&<>"']/g,c=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

function escapeAttr(s){ return escapeHtml(s); }

const _saveOrig = saveDB;

/* ── bridge glue ── */
const __saveOrig = saveDB;
saveDB = function(){ __saveOrig(); bridge.onSave(db); };
export function getDB(){ return db; }
export function setDB(next){ db = next; }
export function bootDB(){ if(!loadDB()){ seedDB(); } return db; }
